// Pure combat model — no Three.js imports so it can be unit tested in Node.

export const PARTS = ['head', 'jaw', 'torso', 'leftArm', 'rightArm', 'leftLeg', 'rightLeg']

export const WEAPONS = {
  sword: {
    id: 'sword',
    name: 'Gladius',
    subtitle: 'Cut · Sever · Bisect',
    sharp: true,
    damage: 30,
    heavyDamage: 72,
    reach: 2.85,
    arc: 0.72,
    windup: 0.09,
    swing: 0.16,
    recovery: 0.26,
    heavyWindup: 0.34,
    heavySwing: 0.22,
    heavyRecovery: 0.38,
    icon: 'sword'
  },
  hammer: {
    id: 'hammer',
    name: 'War Hammer',
    subtitle: 'Crush · Break · Pulverise',
    sharp: false,
    damage: 46,
    heavyDamage: 92,
    reach: 2.55,
    arc: 0.64,
    windup: 0.15,
    swing: 0.2,
    recovery: 0.34,
    heavyWindup: 0.42,
    heavySwing: 0.26,
    heavyRecovery: 0.5,
    icon: 'hammer'
  }
}

const LIMB_HP = {
  head: 90,
  jaw: 42,
  torso: 170,
  leftArm: 92,
  rightArm: 92,
  leftLeg: 96,
  rightLeg: 96
}

const HEALTH_MULTIPLIER = {
  head: 1.85,
  jaw: 1.2,
  torso: 1,
  leftArm: 0.72,
  rightArm: 0.72,
  leftLeg: 0.78,
  rightLeg: 0.78
}

const SHARP_MULTIPLIER = {
  head: 1.25,
  jaw: 1.15,
  torso: 1,
  leftArm: 1.1,
  rightArm: 1.1,
  leftLeg: 1.1,
  rightLeg: 1.1
}

const BLUNT_MULTIPLIER = {
  head: 1.35,
  jaw: 1.3,
  torso: 1,
  leftArm: 1.15,
  rightArm: 1.15,
  leftLeg: 1.15,
  rightLeg: 1.15
}

export function createFighter({ health = 100, weapon = 'sword', seed = 0 } = {}) {
  const limbs = {}
  for (const part of PARTS) {
    limbs[part] = { hp: LIMB_HP[part], maxHp: LIMB_HP[part], severed: false, broken: false }
  }
  return {
    id: `fighter-${seed}`,
    health,
    maxHealth: health,
    weapon,
    weaponDropped: false,
    hasWeapon: weapon !== 'none',
    dead: false,
    deathCause: null,
    crawling: false,
    bisected: false,
    headSplit: false,
    skullOpen: false,
    jawGone: false,
    stagger: 0,
    lastHitPart: null,
    limbs,
    hitsTaken: 0
  }
}

function aliveCheck(fighter) {
  return !fighter.dead && fighter.health > 0
}

/**
 * Apply one weapon strike to an NPC.
 * style: 'sharp' (sword) | 'blunt' (hammer)
 * Returns an ordered list of events consumed by the renderer / gore system.
 */
export function applyHit(fighter, { part, style = 'sharp', damage = 30, heavy = false, direction = [0, 0, 1] }) {
  const events = []
  if (!aliveCheck(fighter) || !PARTS.includes(part)) return { events, killed: false }

  const limb = fighter.limbs[part]
  const sharp = style === 'sharp'
  const multiplier = sharp ? SHARP_MULTIPLIER[part] : BLUNT_MULTIPLIER[part]
  const limbDamage = Math.max(1, damage * multiplier)

  fighter.hitsTaken++
  fighter.lastHitPart = part
  fighter.stagger = Math.max(fighter.stagger, heavy ? 0.65 : 0.3)

  // Limb-level destruction.
  if (sharp) {
    limb.hp -= limbDamage
    if (part === 'head' && (heavy || limb.hp <= 0)) {
      fighter.headSplit = true
      limb.hp = 0
      events.push({ type: 'headSplit', part, heavy, direction })
      events.push({ type: 'blood', part, amount: 46, direction, arterial: true })
      events.push({ type: 'gore', part: 'brain' })
    } else if (part === 'jaw' && (heavy || limb.hp <= 0)) {
      fighter.jawGone = true
      limb.hp = 0
      events.push({ type: 'jawOff', part, style, direction })
      events.push({ type: 'blood', part, amount: 20, direction })
    } else if ((part === 'leftArm' || part === 'rightArm') && limb.hp <= 0) {
      limb.severed = true
      events.push({ type: 'sever', part, style, direction })
      events.push({ type: 'blood', part, amount: 32, direction, arterial: true })
      if (part === 'rightArm' && fighter.hasWeapon) {
        fighter.hasWeapon = false
        fighter.weaponDropped = true
        events.push({ type: 'dropWeapon', part: 'rightArm', direction })
      }
    } else if ((part === 'leftLeg' || part === 'rightLeg') && limb.hp <= 0) {
      limb.severed = true
      events.push({ type: 'sever', part, style, direction })
      events.push({ type: 'blood', part, amount: 30, direction, arterial: true })
      if (!fighter.crawling) {
        fighter.crawling = true
        events.push({ type: 'crawl', part })
      }
    } else if (part === 'torso' && heavy) {
      fighter.bisected = true
      events.push({ type: 'bisect', part, style, direction })
      events.push({ type: 'blood', part: 'torso', amount: 60, direction, arterial: true })
      events.push({ type: 'gore', part: 'guts' })
    } else {
      events.push({ type: 'hit', part, style, heavy, direction })
      events.push({ type: 'blood', part, amount: heavy ? 24 : 14, direction })
    }
  } else {
    limb.hp -= limbDamage
    if (part === 'head' && (limb.hp <= 0 || (heavy && damage >= 80))) {
      fighter.skullOpen = true
      limb.hp = 0
      events.push({ type: 'skullOpen', part, direction })
      events.push({ type: 'blood', part, amount: 42, direction, arterial: true })
      events.push({ type: 'gore', part: 'brain' })
      events.push({ type: 'crack', part })
    } else if (part === 'jaw' && limb.hp <= 0) {
      fighter.jawGone = true
      limb.hp = 0
      events.push({ type: 'jawOff', part, style, direction })
      events.push({ type: 'crack', part })
      events.push({ type: 'blood', part, amount: 16, direction })
    } else if ((part === 'leftArm' || part === 'rightArm') && limb.hp <= 0) {
      limb.broken = true
      events.push({ type: 'break', part, style, direction })
      events.push({ type: 'crack', part })
      events.push({ type: 'blood', part, amount: 18, direction })
      if (part === 'rightArm' && fighter.hasWeapon) {
        fighter.hasWeapon = false
        fighter.weaponDropped = true
        events.push({ type: 'dropWeapon', part: 'rightArm', direction })
      }
    } else if ((part === 'leftLeg' || part === 'rightLeg') && limb.hp <= 0) {
      limb.broken = true
      events.push({ type: 'break', part, style, direction })
      events.push({ type: 'crack', part })
      events.push({ type: 'blood', part, amount: 18, direction })
      if (!fighter.crawling) {
        fighter.crawling = true
        events.push({ type: 'crawl', part })
      }
    } else {
      events.push({ type: 'hit', part, style, heavy, direction })
      events.push({ type: 'blood', part, amount: heavy ? 22 : 12, direction })
    }
  }

  // Vital damage.
  let vitality = damage * HEALTH_MULTIPLIER[part]
  if (fighter.headSplit || fighter.skullOpen) vitality += 999
  if (fighter.bisected) vitality += 999
  if (limb.severed || limb.broken) vitality += 12
  fighter.health = Math.max(0, fighter.health - vitality)

  if (fighter.health <= 0 && !fighter.dead) {
    fighter.dead = true
    fighter.deathCause = fighter.headSplit
      ? 'headSplit'
      : fighter.skullOpen
        ? 'skullOpen'
        : fighter.bisected
          ? 'bisected'
          : 'wounds'
    events.push({ type: 'death', cause: fighter.deathCause, part })
  }

  return { events, killed: fighter.dead }
}

export function pickFallbackPart(normalizedY) {
  if (normalizedY > 0.9) return 'head'
  if (normalizedY > 0.8) return 'jaw'
  if (normalizedY > 0.52) return 'torso'
  if (normalizedY > 0.26) return normalizedY > 0.39 ? 'leftArm' : 'rightArm'
  return normalizedY > 0.13 ? 'rightLeg' : 'leftLeg'
}

export function wavePlan(wave) {
  const total = 2 + Math.floor(wave * 1.4)
  return {
    wave,
    total,
    concurrent: Math.min(2 + Math.floor(wave / 1.5), 7),
    health: 88 + wave * 12,
    speed: 1.18 + Math.min(wave * 0.055, 0.55),
    damage: 7 + Math.min(wave * 1.15, 11),
    attackCooldown: Math.max(0.7, 1.55 - wave * 0.05)
  }
}

export function waveClearBonus(wave) {
  return { heal: 22, score: 100 * wave }
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { applyHit, createFighter, pickFallbackPart, wavePlan } from '../js/model.js'

function hammer(part, { heavy = false } = {}) {
  return { part, style: 'blunt', damage: heavy ? 92 : 46, heavy, direction: [0, 0, 1] }
}
function sword(part, { heavy = false } = {}) {
  return { part, style: 'sharp', damage: heavy ? 72 : 30, heavy, direction: [0, 0, 1] }
}
function eventsOf(result, type) {
  return result.events.filter(event => event.type === type)
}

test('hammer cracks a skull open and kills the gladiator', () => {
  const fighter = createFighter()
  let result = applyHit(fighter, hammer('head'))
  assert.equal(fighter.dead, false, 'one ordinary head blow should not kill')
  result = applyHit(fighter, hammer('head'))
  assert.equal(fighter.skullOpen, true)
  assert.equal(fighter.dead, true)
  assert.equal(fighter.deathCause, 'skullOpen')
  assert.equal(eventsOf(result, 'skullOpen').length, 1)
  assert.equal(eventsOf(result, 'gore')[0].part, 'brain')
})

test('a heavy hammer blow opens the skull in one strike', () => {
  const fighter = createFighter()
  const result = applyHit(fighter, hammer('head', { heavy: true }))
  assert.equal(fighter.skullOpen, true)
  assert.equal(fighter.dead, true)
  assert.equal(eventsOf(result, 'crack').length, 1)
})

test('hammer breaks the jaw clean off', () => {
  const fighter = createFighter()
  const result = applyHit(fighter, hammer('jaw'))
  assert.equal(fighter.jawGone, true)
  assert.equal(fighter.dead, false)
  assert.equal(eventsOf(result, 'jawOff').length, 1)
})

test('breaking the weapon arm drops the weapon and exposes bone', () => {
  const fighter = createFighter({ weapon: 'sword' })
  applyHit(fighter, hammer('rightArm'))
  const result = applyHit(fighter, hammer('rightArm'))
  assert.equal(fighter.limbs.rightArm.broken, true)
  assert.equal(fighter.hasWeapon, false)
  assert.equal(fighter.weaponDropped, true)
  assert.equal(eventsOf(result, 'break').length, 1)
  assert.equal(eventsOf(result, 'dropWeapon').length, 1)
})

test('breaking a leg makes the gladiator crawl', () => {
  const fighter = createFighter()
  applyHit(fighter, hammer('leftLeg'))
  const result = applyHit(fighter, hammer('leftLeg'))
  assert.equal(fighter.limbs.leftLeg.broken, true)
  assert.equal(fighter.crawling, true)
  assert.equal(eventsOf(result, 'crawl').length, 1)
})

test('sword severs an arm and the weapon falls with it', () => {
  const fighter = createFighter({ weapon: 'hammer' })
  applyHit(fighter, sword('rightArm'))
  const result = applyHit(fighter, sword('rightArm'))
  assert.equal(fighter.limbs.rightArm.severed, true)
  assert.equal(fighter.hasWeapon, false)
  assert.equal(eventsOf(result, 'sever').length, 1)
  assert.equal(eventsOf(result, 'dropWeapon').length, 1)
})

test('a heavy sword cut severs a limb in one strike', () => {
  const fighter = createFighter()
  applyHit(fighter, sword('leftArm', { heavy: true }))
  assert.equal(fighter.limbs.leftArm.severed, true)
})

test('severing a leg grounds the gladiator', () => {
  const fighter = createFighter()
  applyHit(fighter, sword('rightLeg', { heavy: true }))
  assert.equal(fighter.limbs.rightLeg.severed, true)
  assert.equal(fighter.crawling, true)
})

test('a heavy sword blow bisects the torso and spills guts', () => {
  const fighter = createFighter({ health: 130 })
  const result = applyHit(fighter, sword('torso', { heavy: true }))
  assert.equal(fighter.bisected, true)
  assert.equal(fighter.dead, true)
  assert.equal(fighter.deathCause, 'bisected')
  assert.equal(eventsOf(result, 'bisect').length, 1)
  assert.equal(eventsOf(result, 'gore')[0].part, 'guts')
  assert.ok(eventsOf(result, 'blood')[0].amount >= 50)
})

test('a heavy sword cut splits the head but leaves the jaw', () => {
  const fighter = createFighter({ health: 200 })
  const result = applyHit(fighter, sword('head', { heavy: true }))
  assert.equal(fighter.headSplit, true)
  assert.equal(fighter.jawGone, false)
  assert.equal(fighter.dead, true)
  assert.equal(eventsOf(result, 'headSplit').length, 1)
})

test('dead fighters ignore further damage', () => {
  const fighter = createFighter()
  applyHit(fighter, sword('head', { heavy: true }))
  const result = applyHit(fighter, hammer('head'))
  assert.equal(result.events.length, 0)
})

test('fallback aim maps screen height to body parts', () => {
  assert.equal(pickFallbackPart(0.95), 'head')
  assert.equal(pickFallbackPart(0.84), 'jaw')
  assert.equal(pickFallbackPart(0.65), 'torso')
  assert.equal(pickFallbackPart(0.32), 'rightArm')
  assert.equal(pickFallbackPart(0.05), 'leftLeg')
})

test('waves scale enemies while keeping concurrency bounded', () => {
  const first = wavePlan(1)
  const tenth = wavePlan(10)
  assert.ok(tenth.total > first.total)
  assert.ok(tenth.health > first.health)
  assert.ok(tenth.speed > first.speed)
  assert.ok(tenth.concurrent <= 7)
  assert.ok(tenth.attackCooldown < first.attackCooldown)
})

import * as THREE from 'three'

function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function canvasTexture(size, draw, { repeat = [1, 1], srgb = true, anisotropy = 8 } = {}) {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  draw(ctx, size)
  const texture = new THREE.CanvasTexture(canvas)
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping
  texture.repeat.set(repeat[0], repeat[1])
  texture.anisotropy = anisotropy
  if (srgb) texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

export function makeSandTexture() {
  return canvasTexture(512, (ctx, size) => {
    const rnd = mulberry32(7)
    const gradient = ctx.createLinearGradient(0, 0, size, size)
    gradient.addColorStop(0, '#c8a46c')
    gradient.addColorStop(0.45, '#d7b37b')
    gradient.addColorStop(1, '#bd9761')
    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, size, size)

    for (let i = 0; i < 9000; i++) {
      const x = rnd() * size
      const y = rnd() * size
      const shade = 120 + Math.floor(rnd() * 90)
      const alpha = 0.05 + rnd() * 0.16
      ctx.fillStyle = `rgba(${shade},${Math.floor(shade * 0.88)},${Math.floor(shade * 0.62)},${alpha})`
      const r = 0.4 + rnd() * 1.9
      ctx.fillRect(x, y, r, r)
    }

    for (let i = 0; i < 22; i++) {
      const x = rnd() * size
      const y = rnd() * size
      const radius = 12 + rnd() * 46
      const patch = ctx.createRadialGradient(x, y, 0, x, y, radius)
      patch.addColorStop(0, `rgba(110,80,44,${0.06 + rnd() * 0.06})`)
      patch.addColorStop(1, 'rgba(110,80,44,0)')
      ctx.fillStyle = patch
      ctx.beginPath()
      ctx.arc(x, y, radius, 0, Math.PI * 2)
      ctx.fill()
    }

    // Raked sand grooves.
    ctx.lineWidth = 1
    for (let i = 0; i < 90; i++) {
      const y = rnd() * size
      ctx.strokeStyle = `rgba(90,62,32,${0.04 + rnd() * 0.07})`
      ctx.beginPath()
      ctx.moveTo(0, y)
      ctx.bezierCurveTo(size * 0.33, y + (rnd() - 0.5) * 18, size * 0.66, y + (rnd() - 0.5) * 18, size, y + (rnd() - 0.5) * 8)
      ctx.stroke()
    }
  }, { repeat: [7, 7] })
}

export function makeStoneTexture() {
  return canvasTexture(512, (ctx, size) => {
    const rnd = mulberry32(19)
    ctx.fillStyle = '#665f51'
    ctx.fillRect(0, 0, size, size)
    const rowHeight = 64
    for (let row = 0; row < size / rowHeight; row++) {
      const offset = row % 2 ? 64 : 0
      for (let col = -1; col < 5; col++) {
        const x = col * 128 + offset
        const y = row * rowHeight
        const tone = 118 + Math.floor(rnd() * 40)
        ctx.fillStyle = `rgb(${tone},${Math.floor(tone * 0.94)},${Math.floor(tone * 0.82)})`
        ctx.fillRect(x + 3, y + 3, 122, rowHeight - 6)
        ctx.strokeStyle = 'rgba(255,244,214,0.14)'
        ctx.lineWidth = 1
        ctx.strokeRect(x + 4.5, y + 4.5, 119, rowHeight - 9)
        for (let i = 0; i < 45; i++) {
          ctx.fillStyle = `rgba(50,44,34,${0.03 + rnd() * 0.1})`
          ctx.fillRect(x + 4 + rnd() * 118, y + 4 + rnd() * (rowHeight - 10), 1 + rnd() * 3, 1 + rnd() * 2)
        }
      }
    }
    ctx.strokeStyle = 'rgba(40,34,26,0.28)'
    ctx.lineWidth = 1.3
    for (let i = 0; i < 12; i++) {
      let x = rnd() * size
      let y = rnd() * size
      ctx.beginPath()
      ctx.moveTo(x, y)
      for (let s = 0; s < 5; s++) {
        x += (rnd() - 0.5) * 44
        y += rnd() * 26
        ctx.lineTo(x, y)
      }
      ctx.stroke()
    }
  }, { repeat: [10, 1.6] })
}

export function makeSplatTexture() {
  return canvasTexture(256, (ctx, size) => {
    const rnd = mulberry32(91)
    ctx.clearRect(0, 0, size, size)
    const cx = size / 2
    const cy = size / 2
    for (let i = 0; i < 16; i++) {
      const angle = rnd() * Math.PI * 2
      const distance = rnd() * 26
      const x = cx + Math.cos(angle) * distance
      const y = cy + Math.sin(angle) * distance
      const radius = 16 + rnd() * 46
      const gradient = ctx.createRadialGradient(x, y, radius * 0.15, x, y, radius)
      gradient.addColorStop(0, 'rgba(255,255,255,0.98)')
      gradient.addColorStop(0.72, 'rgba(255,255,255,0.9)')
      gradient.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gradient
      ctx.beginPath()
      ctx.arc(x, y, radius, 0, Math.PI * 2)
      ctx.fill()
    }
    for (let i = 0; i < 52; i++) {
      const angle = rnd() * Math.PI * 2
      const distance = 44 + rnd() * 74
      const x = cx + Math.cos(angle) * distance
      const y = cy + Math.sin(angle) * distance
      const radius = 1.5 + rnd() * 7
      ctx.fillStyle = `rgba(255,255,255,${0.45 + rnd() * 0.5})`
      ctx.beginPath()
      ctx.arc(x, y, radius, 0, Math.PI * 2)
      ctx.fill()
    }
    // Long arterial streaks.
    for (let i = 0; i < 5; i++) {
      const angle = rnd() * Math.PI * 2
      const length = 40 + rnd() * 70
      ctx.strokeStyle = 'rgba(255,255,255,0.65)'
      ctx.lineWidth = 2 + rnd() * 5
      ctx.beginPath()
      ctx.moveTo(cx + Math.cos(angle) * 18, cy + Math.sin(angle) * 18)
      ctx.lineTo(cx + Math.cos(angle) * length, cy + Math.sin(angle) * length)
      ctx.stroke()
    }
  }, { repeat: [1, 1], srgb: false })
}

export function makeContactShadowTexture() {
  return canvasTexture(128, (ctx, size) => {
    const gradient = ctx.createRadialGradient(size / 2, size / 2, 2, size / 2, size / 2, size / 2)
    gradient.addColorStop(0, 'rgba(0,0,0,0.78)')
    gradient.addColorStop(0.45, 'rgba(0,0,0,0.4)')
    gradient.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, size, size)
  }, { repeat: [1, 1], srgb: false })
}

export function makeBannerTexture() {
  return canvasTexture(256, (ctx, size) => {
    ctx.fillStyle = '#6d1112'
    ctx.fillRect(0, 0, size, size)
    const gradient = ctx.createLinearGradient(0, 0, size, 0)
    gradient.addColorStop(0, 'rgba(0,0,0,0.38)')
    gradient.addColorStop(0.5, 'rgba(255,210,120,0.08)')
    gradient.addColorStop(1, 'rgba(0,0,0,0.42)')
    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, size, size)
    ctx.strokeStyle = '#d8b25a'
    ctx.lineWidth = 8
    ctx.strokeRect(10, 10, size - 20, size - 20)
    ctx.strokeStyle = '#c9a24a'
    ctx.lineWidth = 5
    ctx.beginPath()
    ctx.arc(size / 2, size / 2, 58, 0, Math.PI * 2)
    ctx.stroke()
    // Crossed blades.
    ctx.lineWidth = 9
    ctx.beginPath()
    ctx.moveTo(72, 176)
    ctx.lineTo(184, 74)
    ctx.moveTo(184, 176)
    ctx.lineTo(72, 74)
    ctx.stroke()
    ctx.fillStyle = '#d8b25a'
    ctx.beginPath()
    ctx.arc(size / 2, size / 2, 16, 0, Math.PI * 2)
    ctx.fill()
    for (let i = 0; i < 90; i++) {
      ctx.fillStyle = `rgba(0,0,0,${0.03 + Math.random() * 0.08})`
      ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2)
    }
  }, { repeat: [1, 1] })
}

export function makeWoodTexture() {
  return canvasTexture(256, (ctx, size) => {
    const rnd = mulberry32(44)
    ctx.fillStyle = '#4b3421'
    ctx.fillRect(0, 0, size, size)
    for (let i = 0; i < 55; i++) {
      const y = rnd() * size
      ctx.fillStyle = `rgba(${90 + Math.floor(rnd() * 40)},${58 + Math.floor(rnd() * 26)},${30 + Math.floor(rnd() * 14)},0.35)`
      ctx.fillRect(0, y, size, 1 + rnd() * 4)
    }
    for (let i = 0; i < 8; i++) {
      const x = rnd() * size
      const y = rnd() * size
      ctx.strokeStyle = 'rgba(30,18,10,0.5)'
      ctx.beginPath()
      ctx.ellipse(x, y, 4 + rnd() * 7, 1.5 + rnd() * 3, 0, 0, Math.PI * 2)
      ctx.stroke()
    }
  }, { repeat: [2, 2] })
}

export function makeSplashTexture() {
  return canvasTexture(128, (ctx, size) => {
    const gradient = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
    gradient.addColorStop(0, 'rgba(255,255,255,1)')
    gradient.addColorStop(0.5, 'rgba(255,255,255,0.8)')
    gradient.addColorStop(1, 'rgba(255,255,255,0)')
    ctx.fillStyle = gradient
    ctx.beginPath()
    ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2)
    ctx.fill()
  }, { repeat: [1, 1], srgb: false })
}

import * as THREE from 'three'

const SKIN_TONES = [0x9c6646, 0x7d4f34, 0xb9825c, 0x6b432c, 0xc79770]
const CLOTH_COLORS = [0x7b1f1f, 0x223f6b, 0x3c5b33, 0x7a5a18, 0x56265f, 0x2d6064]
const ARMOR_COLORS = [0xa8813d, 0x7b7f82, 0x8c6a33, 0x676c70]

const geometryCache = new Map()
function geo(key, make) {
  if (!geometryCache.has(key)) geometryCache.set(key, make())
  return geometryCache.get(key)
}

const box = (w, h, d) => geo(`b${w},${h},${d}`, () => new THREE.BoxGeometry(w, h, d))
const cyl = (rt, rb, h, seg = 8) => geo(`c${rt},${rb},${h},${seg}`, () => new THREE.CylinderGeometry(rt, rb, h, seg))
const sph = (r, seg = 12) => geo(`s${r},${seg}`, () => new THREE.SphereGeometry(r, seg, Math.max(6, Math.floor(seg * 0.66))))
const hemi = (r, seg = 12, top = true) => geo(`h${r},${seg},${top}`, () => new THREE.SphereGeometry(r, seg, 8, 0, Math.PI * 2, top ? 0 : Math.PI / 2, Math.PI / 2))

const standard = (color, options = {}) => new THREE.MeshStandardMaterial({ color, roughness: 0.82, metalness: 0.02, ...options })

function mesh(geometry, material, position = [0, 0, 0], scale = [1, 1, 1], rotation = [0, 0, 0]) {
  const m = new THREE.Mesh(geometry, material)
  m.position.set(...position)
  m.scale.set(...scale)
  m.rotation.set(...rotation)
  m.castShadow = true
  m.receiveShadow = true
  return m
}

const hitMaterial = new THREE.MeshBasicMaterial({ colorWrite: false, depthWrite: false, transparent: true, opacity: 0 })
const hitGeo = new THREE.BoxGeometry(1, 1, 1)

function hitbox(size, position = [0, 0, 0]) {
  const m = new THREE.Mesh(hitGeo, hitMaterial)
  m.scale.set(...size)
  m.position.set(...position)
  m.userData.hitbox = true
  return m
}

function seeded(seed) {
  let s = (seed * 2654435761) >>> 0
  return () => {
    s ^= s << 13
    s ^= s >>> 17
    s ^= s << 5
    return (s >>> 0) / 4294967296
  }
}

function buildSword() {
  const group = new THREE.Group()
  const bladeMat = standard(0xd5d9dc, { roughness: 0.28, metalness: 0.55 })
  const bronze = standard(0xa8813d, { roughness: 0.42, metalness: 0.6 })
  const leather = standard(0x3b2413, { roughness: 0.95 })
  group.add(mesh(cyl(0.022, 0.025, 0.22, 8), leather, [0, 0.02, 0]))
  group.add(mesh(sph(0.038, 8), bronze, [0, -0.1, 0]))
  group.add(mesh(box(0.24, 0.03, 0.055), bronze, [0, 0.135, 0]))
  const blade = mesh(box(0.065, 0.78, 0.018), bladeMat, [0, 0.55, 0])
  group.add(blade)
  group.add(mesh(box(0.04, 0.09, 0.015), bladeMat, [0, 0.97, 0], [1, 1, 1], [0, 0, 0]))
  const tip = mesh(cyl(0.001, 0.034, 0.12, 4), bladeMat, [0, 1.06, 0])
  group.add(tip)
  group.userData.blade = blade
  return group
}

function buildHammer() {
  const group = new THREE.Group()
  const iron = standard(0x5d6266, { roughness: 0.48, metalness: 0.65 })
  const darkIron = standard(0x3b4044, { roughness: 0.55, metalness: 0.5 })
  const wood = standard(0x5a3a20, { roughness: 0.9 })
  const bronze = standard(0x9b7534, { roughness: 0.45, metalness: 0.55 })
  group.add(mesh(cyl(0.027, 0.032, 0.72, 8), wood, [0, 0.2, 0]))
  group.add(mesh(cyl(0.04, 0.04, 0.09, 8), bronze, [0, -0.15, 0]))
  group.add(mesh(box(0.19, 0.19, 0.34), iron, [0, 0.6, 0]))
  group.add(mesh(box(0.205, 0.06, 0.28), darkIron, [0, 0.7, 0]))
  group.add(mesh(cyl(0.001, 0.07, 0.18, 4), iron, [0, 0.6, 0.24], [1, 1, 1], [Math.PI / 2, 0, 0]))
  group.add(mesh(cyl(0.001, 0.07, 0.18, 4), iron, [0, 0.6, -0.24], [1, 1, 1], [-Math.PI / 2, 0, 0]))
  group.add(mesh(cyl(0.045, 0.045, 0.05, 8), bronze, [0, 0.46, 0]))
  return group
}

export function createWeapon(type) {
  return type === 'hammer' ? buildHammer() : buildSword()
}

export function createGladiator({ seed = 1, weapon = 'sword' } = {}) {
  const rnd = seeded(seed)
  const skin = standard(SKIN_TONES[Math.floor(rnd() * SKIN_TONES.length)], { roughness: 0.92 })
  const cloth = standard(CLOTH_COLORS[Math.floor(rnd() * CLOTH_COLORS.length)], { roughness: 0.96 })
  const armor = standard(ARMOR_COLORS[Math.floor(rnd() * ARMOR_COLORS.length)], { roughness: 0.4, metalness: 0.62 })
  const darkLeather = standard(0x3b2a1b, { roughness: 0.95 })
  const iron = standard(0x686d71, { roughness: 0.46, metalness: 0.58 })
  const red = standard(0x761616, { roughness: 0.9 })
  const gold = standard(0xc09a4a, { roughness: 0.35, metalness: 0.7 })
  const boneMat = standard(0xeee3c8, { roughness: 0.75 })

  const root = new THREE.Group()
  const pose = new THREE.Group()
  root.add(pose)

  const pelvis = new THREE.Group()
  pelvis.position.y = 0.95
  pose.add(pelvis)
  pelvis.add(mesh(box(0.34, 0.24, 0.25), skin, [0, 0, 0]))
  pelvis.add(mesh(box(0.38, 0.09, 0.29), darkLeather, [0, 0.09, 0]))
  pelvis.add(mesh(box(0.08, 0.08, 0.03), gold, [0, 0.09, 0.16]))
  for (let i = 0; i < 9; i++) {
    const angle = (i / 9) * Math.PI * 2
    const strip = mesh(box(0.075, 0.34, 0.025), i % 2 ? cloth : darkLeather,
      [Math.sin(angle) * 0.17, -0.24, Math.cos(angle) * 0.13],
      [1, 1, 1],
      [0.16 * Math.cos(angle), angle, -0.16 * Math.sin(angle)])
    pelvis.add(strip)
  }

  const legGroups = {}
  const legParts = {}
  for (const side of ['left', 'right']) {
    const sign = side === 'left' ? -1 : 1
    const leg = new THREE.Group()
    leg.position.set(0.13 * sign, -0.03, 0)
    pelvis.add(leg)
    legParts[side] = leg
    leg.add(mesh(box(0.18, 0.46, 0.2), skin, [0, -0.23, 0]))
    leg.add(mesh(box(0.2, 0.2, 0.22), cloth, [0, -0.07, 0.01]))
    leg.add(mesh(sph(0.09, 10), skin, [0, -0.46, 0.01]))
    const shin = new THREE.Group()
    shin.position.y = -0.46
    leg.add(shin)
    legGroups[side] = shin
    shin.add(mesh(box(0.155, 0.42, 0.17), skin, [0, -0.21, 0]))
    shin.add(mesh(box(0.18, 0.26, 0.19), armor, [0, -0.17, 0.015]))
    shin.add(mesh(box(0.18, 0.06, 0.3), darkLeather, [0, -0.42, 0.06]))
    shin.add(mesh(box(0.16, 0.035, 0.34), skin, [0, -0.45, 0.07]))
    shin.add(mesh(box(0.17, 0.025, 0.03), darkLeather, [0, -0.38, 0.16]))
    leg.add(hitbox([0.3, 0.9, 0.32], [0, -0.42, 0]))
    leg.userData.legPart = side
  }

  const chest = new THREE.Group()
  chest.position.y = 0.16
  pelvis.add(chest)
  chest.add(mesh(box(0.44, 0.42, 0.27), skin, [0, 0.17, 0]))
  chest.add(mesh(box(0.47, 0.18, 0.3), cloth, [0, 0.06, 0]))
  const plate = mesh(box(0.43, 0.3, 0.06), armor, [0, 0.19, 0.15])
  chest.add(plate)
  chest.add(mesh(box(0.06, 0.34, 0.04), gold, [0, 0.19, 0.19]))
  chest.add(mesh(box(0.5, 0.07, 0.06), darkLeather, [0, 0.02, 0.14], [1, 1, 1], [0, 0, 0]))
  chest.add(mesh(box(0.075, 0.4, 0.035), darkLeather, [-0.15, 0.17, 0.18], [1, 1, 1], [0, 0, 0.4]))
  chest.add(mesh(box(0.075, 0.4, 0.035), darkLeather, [0.15, 0.17, 0.18], [1, 1, 1], [0, 0, -0.4]))
  chest.add(hitbox([0.56, 0.48, 0.38], [0, 0.19, 0]))

  // Shoulder guards.
  for (const side of [-1, 1]) {
    chest.add(mesh(hemi(0.17, 12, true), armor, [0.3 * side, 0.35, 0], [1, 0.72, 1]))
    chest.add(mesh(box(0.11, 0.1, 0.2), iron, [0.3 * side, 0.36, 0.02]))
  }

  const head = new THREE.Group()
  head.position.y = 0.43
  chest.add(head)
  head.add(mesh(cyl(0.07, 0.09, 0.12, 8), skin, [0, 0.02, 0]))
  const skull = new THREE.Group()
  skull.position.y = 0.16
  head.add(skull)
  const lowerHead = mesh(hemi(0.15, 14, false), skin, [0, 0, 0], [1, 1.05, 0.96])
  skull.add(lowerHead)
  skull.add(mesh(sph(0.075, 8), skin, [0, 0.04, 0.115], [1, 0.7, 0.7]))
  skull.add(mesh(box(0.03, 0.05, 0.04), skin, [0, 0.02, 0.16]))
  for (const side of [-1, 1]) {
    skull.add(mesh(box(0.045, 0.026, 0.02), iron, [0.055 * side, 0.07, 0.137]))
    skull.add(mesh(box(0.075, 0.055, 0.03), skin, [0.09 * side, 0.02, 0.105]))
  }
  skull.add(hitbox([0.36, 0.36, 0.34], [0, 0.03, 0]))

  const cap = new THREE.Group()
  cap.position.y = 0.015
  skull.add(cap)
  cap.add(mesh(hemi(0.158, 14, true), skin, [0, 0, 0], [1, 1, 0.97]))
  const helmetStyle = Math.floor(rnd() * 3)
  if (helmetStyle !== 2) {
    const helmetMat = helmetStyle === 0 ? armor : iron
    cap.add(mesh(hemi(0.172, 12, true), helmetMat, [0, 0.015, 0], [1, 0.94, 1]))
    cap.add(mesh(cyl(0.174, 0.178, 0.055, 14), helmetMat, [0, -0.02, 0]))
    cap.add(mesh(box(0.05, 0.13, 0.06), helmetMat, [0, -0.09, 0.135]))
    if (helmetStyle === 0) {
      cap.add(mesh(box(0.035, 0.12, 0.3), red, [0, 0.19, -0.02]))
      for (let i = 0; i < 4; i++) cap.add(mesh(box(0.05, 0.07 + i * 0.012, 0.055), red, [0, 0.17 + i * 0.015, -0.14 + i * 0.07]))
    }
  } else {
    cap.add(mesh(box(0.31, 0.05, 0.045), cloth, [0, 0.02, 0.05]))
  }
  cap.userData.isCap = true

  const brain = mesh(sph(0.12, 10), standard(0xb0646c, { roughness: 0.7 }), [0, 0.02, 0])
  brain.visible = false
  skull.add(brain)

  const jaw = new THREE.Group()
  jaw.position.set(0, 0.055, 0.055)
  head.add(jaw)
  const jawMesh = mesh(box(0.17, 0.095, 0.13), skin, [0, -0.035, 0.035])
  jaw.add(jawMesh)
  jaw.add(mesh(box(0.15, 0.025, 0.11), darkLeather, [0, -0.075, 0.04]))
  jaw.add(mesh(box(0.15, 0.02, 0.025), standard(0xd8cfb4, { roughness: 0.7 }), [0, -0.004, 0.097]))
  jaw.add(hitbox([0.26, 0.16, 0.24], [0, -0.02, 0.04]))
  jaw.userData.isJaw = true

  const mouth = mesh(box(0.13, 0.07, 0.06), standard(0x370b0b, { roughness: 1 }), [0, 0.04, 0.085])
  mouth.visible = false
  skull.add(mouth)
  const cutDisc = mesh(cyl(0.14, 0.14, 0.035, 12), standard(0x6d1111, { roughness: 0.6 }), [0, 0.02, 0])
  cutDisc.visible = false
  head.add(cutDisc)

  const armparts = {}
  const armGroups = {}
  const weaponPivots = {}
  for (const side of ['left', 'right']) {
    const sign = side === 'left' ? -1 : 1
    const arm = new THREE.Group()
    arm.position.set(0.31 * sign, 0.32, 0)
    chest.add(arm)
    armparts[side] = arm
    arm.add(mesh(box(0.15, 0.34, 0.16), skin, [0, -0.17, 0]))
    arm.add(mesh(box(0.18, 0.17, 0.19), cloth, [0, -0.06, 0]))
    const forearm = new THREE.Group()
    forearm.position.y = -0.35
    arm.add(forearm)
    armGroups[side] = forearm
    forearm.add(mesh(box(0.13, 0.3, 0.14), skin, [0, -0.15, 0]))
    forearm.add(mesh(box(0.155, 0.24, 0.165), darkLeather, [0, -0.16, 0.01]))
    forearm.add(mesh(sph(0.07, 8), skin, [0, -0.33, 0.01]))
    const hand = new THREE.Group()
    hand.position.y = -0.35
    forearm.add(hand)
    weaponPivots[side] = hand
    arm.add(hitbox([0.28, 0.86, 0.3], [0, -0.4, 0]))
    arm.userData.armPart = side
  }

  const weaponPivot = weaponPivots.right
  let weaponMesh = null
  if (weapon !== 'none') {
    weaponMesh = createWeapon(weapon)
    weaponMesh.rotation.x = -0.55
    weaponMesh.rotation.z = -0.08
    weaponMesh.position.y = -0.02
    weaponMesh.scale.setScalar(0.95)
    weaponPivot.add(weaponMesh)
  }

  const contact = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 1.5), new THREE.MeshBasicMaterial({
    map: null,
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  }))
  contact.rotation.x = -Math.PI / 2
  contact.position.y = 0.012
  contact.renderOrder = 1
  root.add(contact)

  const allMeshes = []
  root.traverse(object => { if (object.isMesh && object.material !== hitMaterial) allMeshes.push(object) })

  return {
    root,
    pose,
    pelvis,
    chest,
    head,
    skull,
    cap,
    jaw,
    brain,
    mouth,
    cutDisc,
    armour: armor,
    cloth,
    skin,
    boneMaterial: boneMat,
    parts: {
      head,
      skull,
      jaw,
      cap,
      chest,
      pelvis,
      leftArm: armparts.left,
      rightArm: armparts.right,
      leftForearm: armGroups.left,
      rightForearm: armGroups.right,
      leftLeg: legParts.left,
      rightLeg: legParts.right,
      leftShin: legGroups.left,
      rightShin: legGroups.right
    },
    weaponPivots,
    weaponPivot,
    weaponMesh,
    allMeshes,
    contact,
    hitboxes: [],
    setWeapon(type) {
      if (weaponMesh) weaponPivot.remove(weaponMesh)
      weaponMesh = createWeapon(type)
      weaponMesh.rotation.x = -0.55
      weaponMesh.rotation.z = -0.08
      weaponMesh.position.y = -0.02
      weaponMesh.scale.setScalar(0.95)
      weaponPivot.add(weaponMesh)
      this.weaponMesh = weaponMesh
    },
    showBone(part) {
      const bone = mesh(cyl(0.028, 0.045, 0.26, 6), boneMat, [0, 0, 0])
      const bloodMat = standard(0x5f0d0d, { roughness: 0.55 })
      const blood = mesh(sph(0.06, 6), bloodMat, [0, 0, 0], [1, 0.6, 1])
      if (part === 'leftArm' || part === 'rightArm') {
        const sign = part === 'leftArm' ? -1 : 1
        bone.position.set(0.02 * sign, -0.31, 0.08)
        bone.rotation.set(0.8, 0, 0.35 * sign)
        blood.position.set(0.03 * sign, -0.28, 0.05)
        armparts[part === 'leftArm' ? 'left' : 'right'].add(bone, blood)
      } else {
        const sign = part === 'leftLeg' ? -1 : 1
        bone.position.set(0.03 * sign, -0.4, 0.09)
        bone.rotation.set(0.9, 0, 0.3 * sign)
        blood.position.set(0.02 * sign, -0.37, 0.06)
        legParts[part === 'leftLeg' ? 'left' : 'right'].add(bone, blood)
      }
    },
    showStump(part) {
      const bloodMat = standard(0x5f0d0d, { roughness: 0.5 })
      const stump = mesh(sph(0.075, 8), bloodMat, [0, 0, 0], [1, 0.5, 1])
      if (part === 'rightArm' || part === 'leftArm') {
        const sign = part === 'rightArm' ? 1 : -1
        stump.position.set(0.3 * sign, 0.3, 0)
        chest.add(stump)
      } else if (part === 'rightLeg' || part === 'leftLeg') {
        const sign = part === 'rightLeg' ? 1 : -1
        stump.position.set(0.13 * sign, -0.02, 0)
        pelvis.add(stump)
      }
    },
    showJawSocket() {
      mouth.visible = true
    },
    showBrain() {
      brain.visible = true
      cap.visible = false
      const rim = mesh(cyl(0.15, 0.15, 0.03, 14), standard(0x4d0b0b, { roughness: 0.55 }), [0, 0.16, 0])
      skull.add(rim)
    },
    showHeadCut() {
      cutDisc.visible = true
    },
    showBisectCut(where) {
      const disc = mesh(cyl(0.2, 0.2, 0.035, 14), standard(0x5c0c0c, { roughness: 0.55 }), [0, 0, 0])
      if (where === 'chest') {
        disc.position.y = -0.03
        chest.add(disc)
      } else {
        disc.position.y = 0.13
        pelvis.add(disc)
      }
    }
  }
}

export function createFirstPersonWeapon(type) {
  const group = new THREE.Group()
  const weapon = createWeapon(type)
  weapon.scale.setScalar(1.15)
  group.add(weapon)

  const gloveMat = standard(0x2e1c12, { roughness: 0.88 })
  const strapMat = standard(0x6d4a25, { roughness: 0.9 })
  const steel = standard(0x8a9096, { roughness: 0.35, metalness: 0.55 })
  const glove = new THREE.Group()
  glove.add(mesh(box(0.14, 0.17, 0.15), gloveMat, [0, -0.01, 0]))
  glove.add(mesh(box(0.15, 0.05, 0.16), strapMat, [0, 0.04, 0]))
  glove.add(mesh(sph(0.05, 8), gloveMat, [0.07, 0.03, 0.02]))
  glove.add(mesh(sph(0.045, 8), gloveMat, [0.06, 0.0, 0.06]))
  glove.add(mesh(box(0.18, 0.16, 0.05), steel, [0, -0.1, 0.11], [1, 1, 1], [0.2, 0, 0]))
  glove.position.y = -0.03
  group.add(glove)

  group.userData.weapon = weapon
  return group
}

