import * as THREE from 'three'
import {
  makeSandTexture,
  makeStoneTexture,
  makeBannerTexture,
  makeWoodTexture,
  makeSplashTexture
} from './textures.js'

const TAU = Math.PI * 2

function add(mesh, cast = true, receive = true) {
  mesh.castShadow = cast
  mesh.receiveShadow = receive
  return mesh
}

function archWallGeometry(width, height, openingWidth, openingHeight, depth) {
  const shape = new THREE.Shape()
  shape.moveTo(-width / 2, 0)
  shape.lineTo(width / 2, 0)
  shape.lineTo(width / 2, height)
  shape.lineTo(-width / 2, height)
  shape.lineTo(-width / 2, 0)
  const hole = new THREE.Path()
  const half = openingWidth / 2
  const spring = openingHeight - half
  hole.moveTo(-half, 0)
  hole.lineTo(half, 0)
  hole.lineTo(half, spring)
  hole.absarc(0, spring, half, 0, Math.PI, false)
  hole.lineTo(-half, 0)
  shape.holes.push(hole)
  return new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false, curveSegments: 10 })
}

export function createArena(scene) {
  const group = new THREE.Group()
  scene.add(group)

  scene.fog = new THREE.Fog(0xdcc39a, 58, 150)
  scene.background = new THREE.Color(0x9fc2e6)

  // Sky dome.
  const skyGeo = new THREE.SphereGeometry(160, 32, 20)
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(0x2f6db3) },
      mid: { value: new THREE.Color(0x8fbde6) },
      horizon: { value: new THREE.Color(0xf0d6a6) },
      sunDir: { value: new THREE.Vector3(-0.45, 0.62, 0.38).normalize() }
    },
    vertexShader: `
      varying vec3 vWorld;
      void main() {
        vWorld = (modelMatrix * vec4(position, 1.0)).xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 top; uniform vec3 mid; uniform vec3 horizon; uniform vec3 sunDir;
      varying vec3 vWorld;
      void main() {
        vec3 d = normalize(vWorld);
        float h = clamp(d.y, 0.0, 1.0);
        vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
        col = mix(col, top, smoothstep(0.18, 0.85, h));
        float sun = pow(max(dot(d, sunDir), 0.0), 180.0);
        float haze = pow(max(dot(d, sunDir), 0.0), 8.0);
        col += vec3(1.0, 0.72, 0.36) * sun * 1.6;
        col += vec3(1.0, 0.8, 0.55) * haze * 0.12;
        float clouds = sin(d.x * 13.0 + d.z * 9.0) * sin(d.z * 17.0 - d.x * 7.0);
        col += vec3(1.0, 0.96, 0.9) * smoothstep(0.72, 1.0, clouds) * 0.05 * smoothstep(0.05, 0.4, h);
        gl_FragColor = vec4(col, 1.0);
      }
    `
  })
  const sky = new THREE.Mesh(skyGeo, skyMat)
  sky.frustumCulled = false
  group.add(sky)

  const hemi = new THREE.HemisphereLight(0xcfe4ff, 0xa77a48, 1.15)
  scene.add(hemi)
  const ambient = new THREE.AmbientLight(0xffe9c4, 0.28)
  scene.add(ambient)
  const sun = new THREE.DirectionalLight(0xfff1d4, 3.1)
  sun.position.set(-24, 34, 18)
  sun.castShadow = true
  sun.shadow.mapSize.set(2048, 2048)
  sun.shadow.camera.left = -26
  sun.shadow.camera.right = 26
  sun.shadow.camera.top = 26
  sun.shadow.camera.bottom = -26
  sun.shadow.camera.near = 1
  sun.shadow.camera.far = 90
  sun.shadow.bias = -0.0004
  sun.shadow.normalBias = 0.035
  scene.add(sun)
  scene.add(sun.target)
  sun.target.position.set(0, 0, 0)

  const sandTexture = makeSandTexture()
  const stoneTexture = makeStoneTexture()
  const bannerTexture = makeBannerTexture()
  const woodTexture = makeWoodTexture()

  // Sand floor.
  const floorGeo = new THREE.CircleGeometry(18.6, 112)
  const pos = floorGeo.attributes.position
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i)
    const y = pos.getY(i)
    pos.setZ(i, (Math.sin(x * 1.7) * Math.cos(y * 1.3) + Math.sin(x * 4.3 + y * 2.1) * 0.35) * 0.018)
  }
  floorGeo.computeVertexNormals()
  const sandMat = new THREE.MeshStandardMaterial({ map: sandTexture, color: 0xf0dcb4, roughness: 1, metalness: 0 })
  const floor = new THREE.Mesh(floorGeo, sandMat)
  floor.rotation.x = -Math.PI / 2
  floor.receiveShadow = true
  group.add(floor)

  // Darker disturbed sand ring near the wall.
  const ringMat = new THREE.MeshStandardMaterial({ map: sandTexture, color: 0xbfa079, roughness: 1, transparent: true, opacity: 0.65 })
  const outerRing = new THREE.Mesh(new THREE.RingGeometry(14.6, 18.7, 96), ringMat)
  outerRing.rotation.x = -Math.PI / 2
  outerRing.position.y = 0.006
  outerRing.receiveShadow = true
  group.add(outerRing)

  const stoneMat = new THREE.MeshStandardMaterial({ map: stoneTexture, color: 0xd7cbb4, roughness: 0.94, metalness: 0.02 })
  const darkStone = new THREE.MeshStandardMaterial({ color: 0x4b463d, roughness: 0.96 })
  const trimMat = new THREE.MeshStandardMaterial({ color: 0xc4b08b, roughness: 0.8 })
  const woodMat = new THREE.MeshStandardMaterial({ map: woodTexture, color: 0xc2a077, roughness: 0.92 })
  const bannerMat = new THREE.MeshStandardMaterial({ map: bannerTexture, color: 0xf0c7a9, roughness: 0.95, side: THREE.DoubleSide })
  const ironMat = new THREE.MeshStandardMaterial({ color: 0x4a4f52, roughness: 0.55, metalness: 0.55 })

  // Podium wall with arches.
  const bays = 24
  const wallRadius = 18.75
  const chord = (TAU * wallRadius) / bays * 1.02
  const wallGeo = archWallGeometry(chord, 3.6, 2.15, 2.65, 0.6)
  for (let i = 0; i < bays; i++) {
    const angle = (i / bays) * TAU
    const wall = new THREE.Mesh(wallGeo, stoneMat)
    wall.position.set(Math.sin(angle) * wallRadius, 0, Math.cos(angle) * wallRadius)
    wall.rotation.y = angle
    add(wall)
    group.add(wall)

    // Recess behind the arch.
    const recess = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 2.9), new THREE.MeshBasicMaterial({ color: 0x17130f }))
    recess.position.set(Math.sin(angle) * (wallRadius + 0.66), 1.35, Math.cos(angle) * (wallRadius + 0.66))
    recess.rotation.y = angle + Math.PI
    group.add(recess)

    // Pillar caps.
    const pillar = new THREE.Mesh(new THREE.BoxGeometry(0.28, 3.75, 0.75), trimMat)
    pillar.position.set(Math.sin(angle) * (wallRadius - 0.13), 1.87, Math.cos(angle) * (wallRadius - 0.13))
    pillar.rotation.y = angle
    add(pillar)
    group.add(pillar)
  }

  // Ledge along the podium.
  const ledge = new THREE.Mesh(new THREE.TorusGeometry(wallRadius - 0.1, 0.17, 6, 128), trimMat)
  ledge.rotation.x = Math.PI / 2
  ledge.position.y = 3.62
  add(ledge)
  group.add(ledge)

  // Seating tiers.
  const tierCount = 5
  for (let tier = 0; tier < tierCount; tier++) {
    const radius = 19.1 + tier * 1.75
    const y = 3.9 + tier * 0.98
    const riser = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 0.96, 96, 1, true), stoneMat)
    riser.position.y = y - 0.48
    riser.material.side = THREE.DoubleSide
    add(riser, false, true)
    group.add(riser)

    const seat = new THREE.Mesh(new THREE.RingGeometry(radius, radius + 1.72, 96), new THREE.MeshStandardMaterial({
      color: 0xb8a68a, roughness: 0.98, side: THREE.DoubleSide
    }))
    seat.rotation.x = -Math.PI / 2
    seat.position.y = y + 0.01
    add(seat, false, true)
    group.add(seat)

    const lip = new THREE.Mesh(new THREE.TorusGeometry(radius + 0.06, 0.075, 5, 96), trimMat)
    lip.rotation.x = Math.PI / 2
    lip.position.y = y + 0.02
    group.add(lip)
  }

  // Outer wall.
  const outerWall = new THREE.Mesh(new THREE.CylinderGeometry(28.2, 28.2, 15, 96, 1, true), stoneMat)
  outerWall.position.y = 10.4
  outerWall.material = stoneMat.clone()
  outerWall.material.side = THREE.BackSide
  outerWall.material.map = stoneTexture.clone()
  outerWall.material.map.repeat.set(20, 3)
  outerWall.material.map.needsUpdate = true
  add(outerWall, false, true)
  group.add(outerWall)

  const topRing = new THREE.Mesh(new THREE.TorusGeometry(28.2, 0.32, 6, 128), trimMat)
  topRing.rotation.x = Math.PI / 2
  topRing.position.y = 17.9
  group.add(topRing)

  // Imperial box.
  const boxAngle = -Math.PI / 2
  const boxGroup = new THREE.Group()
  const boxPos = new THREE.Vector3(Math.sin(boxAngle) * 20.4, 4.75, Math.cos(boxAngle) * 20.4)
  boxGroup.position.copy(boxPos)
  boxGroup.rotation.y = boxAngle + Math.PI
  const platform = new THREE.Mesh(new THREE.BoxGeometry(6.2, 0.7, 3.2), trimMat)
  platform.position.y = -0.2
  add(platform)
  boxGroup.add(platform)
  for (const x of [-2.6, 2.6]) {
    for (const z of [-1.2, 1.2]) {
      const column = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 2.8, 10), trimMat)
      column.position.set(x, 1.5, z)
      add(column)
      boxGroup.add(column)
    }
  }
  const canopy = new THREE.Mesh(new THREE.BoxGeometry(6.8, 0.16, 3.6), new THREE.MeshStandardMaterial({ color: 0x701a1c, roughness: 0.9 }))
  canopy.position.y = 3
  add(canopy)
  boxGroup.add(canopy)
  const canopyFront = new THREE.Mesh(new THREE.BoxGeometry(6.8, 0.7, 0.1), new THREE.MeshStandardMaterial({ color: 0x8c2526, roughness: 0.9 }))
  canopyFront.position.set(0, 2.7, 1.8)
  boxGroup.add(canopyFront)
  group.add(boxGroup)

  // Banners hung on the podium.
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * TAU + 0.13
    const banner = new THREE.Mesh(new THREE.PlaneGeometry(1.45, 2.1), bannerMat)
    banner.position.set(Math.sin(angle) * (wallRadius - 0.34), 2.35, Math.cos(angle) * (wallRadius - 0.34))
    banner.rotation.y = angle + Math.PI
    banner.receiveShadow = true
    group.add(banner)
    const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 1.7, 6), woodMat)
    rod.rotation.z = Math.PI / 2
    rod.rotation.y = angle
    rod.position.set(Math.sin(angle) * (wallRadius - 0.3), 3.42, Math.cos(angle) * (wallRadius - 0.3))
    group.add(rod)
  }

  // Scattered props near the walls.
  const props = new THREE.Group()
  group.add(props)
  const crateSpots = [
    [-15.2, 10.4], [15.8, -8.5], [-11.8, -13.2], [13.4, 11.6], [-16.5, -3], [9.5, 15.4]
  ]
  for (const [x, z] of crateSpots) {
    const size = 0.7 + Math.random() * 0.35
    const crate = new THREE.Mesh(new THREE.BoxGeometry(size, size, size), woodMat)
    crate.position.set(x, size / 2, z)
    crate.rotation.y = Math.random() * Math.PI
    add(crate)
    props.add(crate)
    if (Math.random() > 0.4) {
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.36, 0.9, 12), woodMat)
      barrel.position.set(x + 0.6, 0.45, z + 0.45)
      barrel.rotation.y = Math.random() * Math.PI
      add(barrel)
      props.add(barrel)
    }
  }

  // Weapon rack.
  const rack = new THREE.Group()
  rack.position.set(16.2, 0, 3.2)
  rack.rotation.y = -0.7
  const rail = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.1, 0.1), woodMat)
  rail.position.y = 1.35
  add(rail)
  rack.add(rail)
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.12, 1.4, 0.12), woodMat)
    post.position.set(0.8 * side, 0.7, 0)
    add(post)
    rack.add(post)
  }
  for (let i = 0; i < 5; i++) {
    const spear = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.022, 2.1, 5), woodMat)
    spear.position.set(-0.65 + i * 0.32, 1.05, 0.08)
    spear.rotation.z = 0.14 * (i - 2)
    add(spear)
    rack.add(spear)
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.18, 4), ironMat)
    tip.position.set(-0.65 + i * 0.32 + Math.sin(0.14 * (i - 2)) * 1.05, 2.15, 0.08)
    rack.add(tip)
  }
  props.add(rack)

  // Shields against the wall.
  for (let i = 0; i < 7; i++) {
    const angle = i * 1.37 + 0.4
    const shield = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 0.07, 18), i % 2 ? ironMat : trimMat)
    shield.rotation.x = Math.PI / 2
    shield.rotation.z = angle
    shield.position.set(Math.sin(angle) * 17.9, 0.55 + (i % 2) * 0.12, Math.cos(angle) * 17.9)
    add(shield)
    props.add(shield)
  }

  // Dust motes.
  const dustCount = 260
  const dustGeo = new THREE.BufferGeometry()
  const dustPositions = new Float32Array(dustCount * 3)
  const dustPhase = new Float32Array(dustCount)
  for (let i = 0; i < dustCount; i++) {
    const radius = Math.sqrt(Math.random()) * 17
    const angle = Math.random() * TAU
    dustPositions[i * 3] = Math.cos(angle) * radius
    dustPositions[i * 3 + 1] = 0.2 + Math.random() * 5.5
    dustPositions[i * 3 + 2] = Math.sin(angle) * radius
    dustPhase[i] = Math.random() * TAU
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPositions, 3))
  const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
    map: makeSplashTexture(),
    color: 0xffe9c2,
    size: 0.075,
    transparent: true,
    opacity: 0.42,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  }))
  group.add(dust)

  return {
    group,
    floor,
    wallRadius,
    playRadius: 16.6,
    spawnRadius: 16.9,
    sandTexture,
    stoneTexture,
    update(dt, time) {
      const positions = dustGeo.attributes.position.array
      for (let i = 0; i < dustCount; i++) {
        positions[i * 3 + 1] += dt * (0.06 + (i % 5) * 0.008)
        positions[i * 3] += Math.sin(time * 0.3 + dustPhase[i]) * dt * 0.04
        if (positions[i * 3 + 1] > 6.2) positions[i * 3 + 1] = 0.2
      }
      dustGeo.attributes.position.needsUpdate = true
    }
  }
}

import * as THREE from 'three'

const TAU = Math.PI * 2

const TUNICS = [0x7b2222, 0x2d4b72, 0x3d5b33, 0x8a6a25, 0x5a2e60, 0x2b5f61, 0x8b4a27, 0x6b6b6b]
const SKINS = [0xb9825c, 0x8d5a3b, 0xd2a17b, 0x6b432c, 0xc08b63]

function pick(array, rnd) {
  return array[Math.floor(rnd() * array.length)]
}

export function createCrowd(arena) {
  const rnd = (() => {
    let s = 1234567
    return () => {
      s = (s * 1664525 + 1013904223) >>> 0
      return s / 4294967296
    }
  })()

  const people = []
  const centre = new THREE.Vector3()
  const tiers = 5
  for (let tier = 0; tier < tiers; tier++) {
    const radius = 19.1 + tier * 1.75 + 1.0
    const y = 3.9 + tier * 0.98 + 0.26
    const count = Math.min(96, Math.max(60, Math.floor((TAU * radius) / 1.45)))
    for (let i = 0; i < count; i++) {
      const angle = (i / count) * TAU + (rnd() - 0.5) * 0.1
      const towardCenter = angle + Math.PI
      const scale = 0.85 + rnd() * 0.35
      people.push({
        x: Math.sin(angle) * radius,
        y: y + rnd() * 0.12,
        z: Math.cos(angle) * radius,
        angle: towardCenter,
        scale,
        phase: rnd() * TAU,
        speed: 0.7 + rnd() * 0.7,
        jump: rnd() > 0.72,
        bodyColor: new THREE.Color(pick(TUNICS, rnd)),
        skinColor: new THREE.Color(pick(SKINS, rnd))
      })
    }
  }

  const bodyGeo = new THREE.CylinderGeometry(0.15, 0.22, 0.46, 6)
  const headGeo = new THREE.SphereGeometry(0.105, 8, 6)
  const armGeo = new THREE.BoxGeometry(0.06, 0.34, 0.06)
  armGeo.translate(0, -0.17, 0)

  const bodyMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95 })
  const headMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 })
  const armMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95 })

  const bodies = new THREE.InstancedMesh(bodyGeo, bodyMat, people.length)
  const heads = new THREE.InstancedMesh(headGeo, headMat, people.length)
  const arms = new THREE.InstancedMesh(armGeo, armMat, people.length * 2)
  bodies.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
  heads.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
  arms.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
  bodies.frustumCulled = false
  heads.frustumCulled = false
  arms.frustumCulled = false

  const matrix = new THREE.Matrix4()
  const quat = new THREE.Quaternion()
  const pos = new THREE.Vector3()
  const scl = new THREE.Vector3()
  const armQuat = new THREE.Quaternion()
  const armMatrix = new THREE.Matrix4()
  const up = new THREE.Vector3(0, 1, 0)

  for (let i = 0; i < people.length; i++) {
    const p = people[i]
    bodies.setColorAt(i, p.bodyColor)
    heads.setColorAt(i, p.skinColor)
    arms.setColorAt(i * 2, p.bodyColor)
    arms.setColorAt(i * 2 + 1, p.bodyColor)
    quat.setFromAxisAngle(up, p.angle)
    scl.set(p.scale, p.scale, p.scale)

    matrix.compose(pos.set(p.x, p.y, p.z), quat, scl)
    bodies.setMatrixAt(i, matrix)

    matrix.compose(pos.set(p.x, p.y + 0.37 * p.scale, p.z), quat, scl)
    heads.setMatrixAt(i, matrix)

    for (let side = 0; side < 2; side++) {
      const sign = side === 0 ? -1 : 1
      const offsetX = Math.cos(p.angle) * 0.17 * sign
      const offsetZ = -Math.sin(p.angle) * 0.17 * sign
      armQuat.setFromEuler(new THREE.Euler(0, p.angle, sign * 0.18))
      armMatrix.compose(
        pos.set(p.x + offsetX, p.y + 0.16 * p.scale, p.z + offsetZ),
        armQuat,
        scl
      )
      arms.setMatrixAt(i * 2 + side, armMatrix)
    }
    p.armSide = i * 2
  }
  bodies.instanceMatrix.needsUpdate = true
  heads.instanceMatrix.needsUpdate = true
  arms.instanceMatrix.needsUpdate = true
  if (bodies.instanceColor) bodies.instanceColor.needsUpdate = true
  if (heads.instanceColor) heads.instanceColor.needsUpdate = true
  if (arms.instanceColor) arms.instanceColor.needsUpdate = true

  const group = new THREE.Group()
  group.add(bodies, heads, arms)
  arena.group.add(group)

  let cheerEnergy = 0
  let cheerTime = 0
  let armsRaised = false
  const cheerDuration = 2.6

  return {
    group,
    count: people.length,
    cheer(strength = 1) {
      cheerEnergy = Math.min(1.4, cheerEnergy + strength)
      cheerTime = cheerDuration
    },
    update(dt, time) {
      cheerTime = Math.max(0, cheerTime - dt)
      const target = cheerTime > 0 ? Math.min(1.25, cheerEnergy) : 0
      cheerEnergy += (target - cheerEnergy) * Math.min(1, dt * 5)
      const energy = cheerEnergy
      const raised = energy > 0.25

      if (raised !== armsRaised) {
        armsRaised = raised
        for (let i = 0; i < people.length; i++) {
          const p = people[i]
          for (let side = 0; side < 2; side++) {
            const sign = side === 0 ? -1 : 1
            const offsetX = Math.cos(p.angle) * 0.17 * sign
            const offsetZ = -Math.sin(p.angle) * 0.17 * sign
            const zRot = raised ? -sign * (2.15 + 0.22 * Math.sin(time * 9 + p.phase)) : sign * 0.18
            armQuat.setFromEuler(new THREE.Euler(0, p.angle, zRot))
            armMatrix.compose(
              pos.set(p.x + offsetX, p.y + 0.16 * p.scale, p.z + offsetZ),
              armQuat,
              scl.set(p.scale, p.scale, p.scale)
            )
            arms.setMatrixAt(p.armSide + side, armMatrix)
          }
        }
        arms.instanceMatrix.needsUpdate = true
      }

      for (let i = 0; i < people.length; i++) {
        const p = people[i]
        const bob = Math.sin(time * p.speed * 1.6 + p.phase) * (0.018 + energy * 0.055)
        let jump = 0
        if (energy > 0.15 && p.jump) {
          const jumpWave = Math.max(0, Math.sin(time * 7.5 + p.phase * 2.3))
          jump = jumpWave * energy * 0.16
        }
        quat.setFromAxisAngle(up, p.angle)
        scl.set(p.scale, p.scale, p.scale)
        matrix.compose(pos.set(p.x, p.y + bob + jump, p.z), quat, scl)
        bodies.setMatrixAt(i, matrix)
        matrix.compose(pos.set(p.x, p.y + 0.37 * p.scale + bob + jump, p.z), quat, scl)
        heads.setMatrixAt(i, matrix)
        if (raised) {
          for (let side = 0; side < 2; side++) {
            const sign = side === 0 ? -1 : 1
            const offsetX = Math.cos(p.angle) * 0.17 * sign
            const offsetZ = -Math.sin(p.angle) * 0.17 * sign
            const zRot = -sign * (2.15 + 0.22 * Math.sin(time * 9 + p.phase))
            armQuat.setFromEuler(new THREE.Euler(0, p.angle, zRot))
            armMatrix.compose(
              pos.set(p.x + offsetX, p.y + 0.16 * p.scale + bob + jump, p.z + offsetZ),
              armQuat,
              scl
            )
            arms.setMatrixAt(p.armSide + side, armMatrix)
          }
        }
      }
      bodies.instanceMatrix.needsUpdate = true
      heads.instanceMatrix.needsUpdate = true
      if (raised) arms.instanceMatrix.needsUpdate = true
    }
  }
}

import * as THREE from 'three'
import { makeSplatTexture, makeSplashTexture } from './textures.js'

const MAX_PARTICLES = 1100
const MAX_GROUND_SPLATS = 380
const MAX_WALL_SPLATS = 180

const BLOOD_COLORS = [0x5e0809, 0x740a0b, 0x8a0e0e, 0x67090a]

function randomRange(min, max) {
  return min + Math.random() * (max - min)
}

function tint(index) {
  return new THREE.Color(BLOOD_COLORS[index % BLOOD_COLORS.length]).multiplyScalar(randomRange(0.8, 1.15))
}

export function createGore(scene, arena, contactShadowTexture) {
  const root = new THREE.Group()
  root.name = 'gore-debris'
  scene.add(root)

  const splatTexture = makeSplatTexture()
  const splashTexture = makeSplashTexture()

  // ---------------- Blood particles ----------------
  const particleGeo = new THREE.BufferGeometry()
  const positions = new Float32Array(MAX_PARTICLES * 3)
  const sizes = new Float32Array(MAX_PARTICLES)
  const alphas = new Float32Array(MAX_PARTICLES)
  particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  particleGeo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1))
  particleGeo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1))

  const particleMat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    uniforms: {},
    vertexShader: `
      attribute float aSize;
      attribute float aAlpha;
      varying float vAlpha;
      void main() {
        vAlpha = aAlpha;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = clamp(aSize * 380.0 / max(0.5, -mv.z), 1.0, 64.0);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      varying float vAlpha;
      void main() {
        vec2 c = gl_PointCoord - vec2(0.5);
        float d = length(c);
        if (d > 0.5) discard;
        float a = smoothstep(0.5, 0.08, d) * vAlpha;
        vec3 col = mix(vec3(0.28, 0.008, 0.01), vec3(0.72, 0.04, 0.035), smoothstep(0.1, 0.5, a));
        gl_FragColor = vec4(col, a);
      }
    `
  })
  const points = new THREE.Points(particleGeo, particleMat)
  points.frustumCulled = false
  points.renderOrder = 6
  scene.add(points)

  const particles = []
  for (let i = 0; i < MAX_PARTICLES; i++) {
    particles.push({ life: 0, maxLife: 1, vx: 0, vy: 0, vz: 0, size: 0.05, ground: false })
  }
  let particleCursor = 0

  // ---------------- Decals ----------------
  const groundGeo = new THREE.PlaneGeometry(1, 1)
  groundGeo.rotateX(-Math.PI / 2)
  const groundMat = new THREE.MeshBasicMaterial({
    map: splatTexture,
    transparent: true,
    opacity: 0.95,
    depthWrite: false,
    color: 0xffffff,
    polygonOffset: true,
    polygonOffsetFactor: -2
  })
  const groundSplats = new THREE.InstancedMesh(groundGeo, groundMat, MAX_GROUND_SPLATS)
  groundSplats.count = 0
  groundSplats.frustumCulled = false
  groundSplats.renderOrder = 2
  scene.add(groundSplats)
  let groundCount = 0

  const wallGeo = new THREE.PlaneGeometry(1, 1)
  const wallMat = new THREE.MeshBasicMaterial({
    map: splatTexture,
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
    color: 0xffffff,
    side: THREE.DoubleSide,
    polygonOffset: true,
    polygonOffsetFactor: -2
  })
  const wallSplats = new THREE.InstancedMesh(wallGeo, wallMat, MAX_WALL_SPLATS)
  wallSplats.count = 0
  wallSplats.frustumCulled = false
  wallSplats.renderOrder = 2
  scene.add(wallSplats)
  let wallCount = 0

  const dummy = new THREE.Object3D()
  const quatY = new THREE.Quaternion()
  const up = new THREE.Vector3(0, 1, 0)

  function addGroundSplat(x, z, scale = 1) {
    if (groundCount >= MAX_GROUND_SPLATS) return
    const radius = Math.hypot(x, z)
    if (radius > arena.wallRadius) return
    const distance = scale * randomRange(0.55, 1.2)
    dummy.position.set(x + randomRange(-0.2, 0.2), 0.024 + groundCount * 0.00035, z + randomRange(-0.2, 0.2))
    quatY.setFromAxisAngle(up, Math.random() * Math.PI * 2)
    dummy.quaternion.copy(quatY)
    dummy.scale.set(distance, 1, distance)
    dummy.updateMatrix()
    groundSplats.setMatrixAt(groundCount, dummy.matrix)
    groundSplats.setColorAt(groundCount, tint(groundCount))
    groundCount++
    groundSplats.count = groundCount
    groundSplats.instanceMatrix.needsUpdate = true
    if (groundSplats.instanceColor) groundSplats.instanceColor.needsUpdate = true
  }

  function addWallSplat(x, z, y, scale = 1) {
    if (wallCount >= MAX_WALL_SPLATS) return
    const angle = Math.atan2(x, z)
    const radius = arena.wallRadius - 0.18
    dummy.position.set(Math.sin(angle) * radius, y, Math.cos(angle) * radius)
    dummy.rotation.set(0, angle + Math.PI, randomRange(-0.35, 0.35))
    const distance = scale * randomRange(0.6, 1.35)
    dummy.scale.set(distance, distance, 1)
    dummy.updateMatrix()
    wallSplats.setMatrixAt(wallCount, dummy.matrix)
    wallSplats.setColorAt(wallCount, tint(wallCount + 2))
    wallCount++
    wallSplats.count = wallCount
    wallSplats.instanceMatrix.needsUpdate = true
    if (wallSplats.instanceColor) wallSplats.instanceColor.needsUpdate = true
  }

  function wallSplashFrom(position, direction, strength = 1) {
    // Where the spray would meet the arena wall.
    const ox = position.x
    const oz = position.z
    const dx = direction.x
    const dz = direction.z
    const R = arena.wallRadius - 0.4
    const a = dx * dx + dz * dz
    if (a < 0.0001) return
    const b = 2 * (ox * dx + oz * dz)
    const c = ox * ox + oz * oz - R * R
    const disc = b * b - 4 * a * c
    if (disc < 0) return
    const t = (-b + Math.sqrt(disc)) / (2 * a)
    if (t < 0.4 || t > 9) return
    const x = ox + dx * t
    const z = oz + dz * t
    const y = THREE.MathUtils.clamp(position.y + direction.y * t * 0.4 + randomRange(-0.25, 0.6), 0.35, 3.2)
    const count = Math.max(1, Math.round(strength * randomRange(1, 3)))
    for (let i = 0; i < count; i++) addWallSplat(x + randomRange(-0.5, 0.5), z + randomRange(-0.5, 0.5), y + randomRange(-0.25, 0.35), randomRange(0.35, 0.7) * strength)
  }

  // ---------------- Debris ----------------
  const debris = []

  function addDebris(object, { velocity = new THREE.Vector3(), spin = new THREE.Vector3(), life = 45, contact = 0 } = {}) {
    if (!object) return null
    root.attach(object)
    object.traverse(child => {
      if (child.isMesh) {
        child.castShadow = true
        child.receiveShadow = true
      }
    })
    const item = {
      object,
      velocity: velocity.clone(),
      spin: spin.clone(),
      life,
      age: 0,
      contact,
      settled: false
    }
    debris.push(item)
    return item
  }

  function spawnGuts(position, direction) {
    const colors = [0x9c3f48, 0xb8565d, 0x7b2d36, 0xc06a6a, 0x8c2f2d]
    const blobGeo = new THREE.IcosahedronGeometry(0.1, 1)
    const ropeGeo = new THREE.CapsuleGeometry(0.035, 0.38, 2, 6)
    for (let i = 0; i < 16; i++) {
      const mat = new THREE.MeshStandardMaterial({
        color: colors[i % colors.length],
        roughness: 0.55,
        metalness: 0.02
      })
      const isRope = i % 4 === 0
      const blob = new THREE.Mesh(isRope ? ropeGeo : blobGeo, mat)
      blob.scale.set(randomRange(0.7, 1.6), randomRange(0.65, 1.3), randomRange(0.7, 1.5))
      blob.position.set(
        position.x + randomRange(-0.16, 0.16),
        position.y + randomRange(-0.15, 0.2),
        position.z + randomRange(-0.16, 0.16)
      )
      blob.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3)
      const spread = 1.5
      const vel = new THREE.Vector3(
        direction.x * randomRange(0.4, 2.2) + randomRange(-spread, spread),
        randomRange(0.8, 2.6),
        direction.z * randomRange(0.4, 2.2) + randomRange(-spread, spread)
      )
      blob.castShadow = true
      scene.add(blob)
      root.attach(blob)
      debris.push({ object: blob, velocity: vel, spin: new THREE.Vector3(randomRange(-6, 6), randomRange(-6, 6), randomRange(-6, 6)), life: 45, age: 0, settled: false })
    }
    addGroundSplat(position.x, position.z, 1.5)
    addGroundSplat(position.x + direction.x * 0.8, position.z + direction.z * 0.8, 1.1)
    spawnBlood(position, direction, 40, { arterial: true, speed: 3 })
    wallSplashFrom(position, direction, 1.6)
  }

  function spawnBlood(position, direction, amount = 16, { arterial = false, speed = 1, colorSeed = 0 } = {}) {
    const count = Math.max(1, Math.min(80, Math.round(amount)))
    for (let i = 0; i < count; i++) {
      const p = particles[particleCursor]
      particleCursor = (particleCursor + 1) % MAX_PARTICLES
      p.life = randomRange(0.45, arterial ? 1.15 : 0.8)
      p.maxLife = p.life
      p.vx = direction.x * randomRange(0.4, arterial ? 4.6 : 2.5) * speed + randomRange(-1.6, 1.6)
      p.vz = direction.z * randomRange(0.4, arterial ? 4.6 : 2.5) * speed + randomRange(-1.6, 1.6)
      p.vy = randomRange(0.4, arterial ? 4.2 : 2.6)
      p.size = randomRange(0.035, arterial ? 0.16 : 0.1)
      p.ground = false
      const idx = particleCursor === 0 ? MAX_PARTICLES - 1 : particleCursor - 1
      positions[idx * 3] = position.x + randomRange(-0.08, 0.08)
      positions[idx * 3 + 1] = position.y + randomRange(-0.12, 0.12)
      positions[idx * 3 + 2] = position.z + randomRange(-0.08, 0.08)
      sizes[idx] = p.size
      alphas[idx] = 1
    }
    particleGeo.attributes.position.needsUpdate = true
    particleGeo.attributes.aSize.needsUpdate = true
    particleGeo.attributes.aAlpha.needsUpdate = true
  }

  function splatter(position, direction, power = 1) {
    spawnBlood(position, direction, 12 + power * 10, { speed: 1 + power * 0.35 })
    const spread = 0.8 + power * 0.5
    addGroundSplat(position.x + randomRange(-spread, spread), position.z + randomRange(-spread, spread), 0.55 + power * 0.6)
    addGroundSplat(position.x + direction.x * 0.7, position.z + direction.z * 0.7, 0.45 + power * 0.45)
    wallSplashFrom(position, direction, power)
  }

  function addCorpsePool(position, scale = 1.6) {
    addGroundSplat(position.x, position.z, scale)
    addGroundSplat(position.x + randomRange(-0.4, 0.4), position.z + randomRange(-0.4, 0.4), scale * 0.7)
  }

  function spawnBone(position, velocity = new THREE.Vector3(0, 1, 0)) {
    const bone = new THREE.Mesh(
      new THREE.CylinderGeometry(0.024, 0.04, 0.24, 6),
      new THREE.MeshStandardMaterial({ color: 0xefe5cc, roughness: 0.72 })
    )
    bone.position.copy(position)
    bone.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3)
    bone.castShadow = true
    scene.add(bone)
    addDebris(bone, { velocity, spin: new THREE.Vector3(randomRange(-8, 8), randomRange(-8, 8), randomRange(-8, 8)), life: 45 })
  }

  function clear() {
    for (const item of debris) {
      if (item.object.parent) item.object.parent.remove(item.object)
    }
    debris.length = 0
    for (const p of particles) {
      p.life = 0
    }
    alphas.fill(0)
    particleGeo.attributes.aAlpha.needsUpdate = true
    groundCount = 0
    wallCount = 0
    groundSplats.count = 0
    wallSplats.count = 0
  }

  function update(dt) {
    // Particles.
    let dirty = false
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = particles[i]
      if (p.life <= 0) {
        if (alphas[i] !== 0) {
          alphas[i] = 0
          dirty = true
        }
        continue
      }
      p.life -= dt
      if (p.life <= 0) {
        alphas[i] = 0
        dirty = true
        continue
      }
      const idx = i
      const drag = Math.pow(0.12, dt)
      p.vx *= drag
      p.vz *= drag
      p.vy -= 12 * dt
      positions[idx * 3] += p.vx * dt
      positions[idx * 3 + 1] += p.vy * dt
      positions[idx * 3 + 2] += p.vz * dt
      const radius = Math.hypot(positions[idx * 3], positions[idx * 3 + 2])
      if (positions[idx * 3 + 1] <= 0.03 && p.vy < 0) {
        if (Math.random() < 0.075) addGroundSplat(positions[idx * 3], positions[idx * 3 + 2], randomRange(0.2, 0.5))
        p.life = 0
        alphas[idx] = 0
      } else if (radius > arena.wallRadius - 0.2 && Math.random() < 0.09) {
        addWallSplat(positions[idx * 3], positions[idx * 3 + 2], positions[idx * 3 + 1], randomRange(0.2, 0.45))
        p.life = 0
        alphas[idx] = 0
      } else {
        alphas[idx] = Math.min(1, p.life / Math.max(0.1, p.maxLife * 0.55))
      }
      dirty = true
    }
    if (dirty) {
      particleGeo.attributes.position.needsUpdate = true
      particleGeo.attributes.aAlpha.needsUpdate = true
      particleGeo.attributes.aSize.needsUpdate = true
    }

    // Debris physics.
    for (let i = debris.length - 1; i >= 0; i--) {
      const item = debris[i]
      item.age += dt
      if (item.age > item.life) {
        if (item.object.parent) item.object.parent.remove(item.object)
        debris.splice(i, 1)
        continue
      }
      if (item.settled) continue
      const obj = item.object
      item.velocity.y -= 16 * dt
      obj.position.x += item.velocity.x * dt
      obj.position.y += item.velocity.y * dt
      obj.position.z += item.velocity.z * dt
      obj.rotation.x += item.spin.x * dt
      obj.rotation.y += item.spin.y * dt
      obj.rotation.z += item.spin.z * dt
      const radius = Math.hypot(obj.position.x, obj.position.z)
      if (radius > arena.wallRadius - 0.5) {
        const scale = (arena.wallRadius - 0.5) / radius
        obj.position.x *= scale
        obj.position.z *= scale
        item.velocity.x *= -0.25
        item.velocity.z *= -0.25
      }
      if (obj.position.y <= 0.08) {
        obj.position.y = 0.08
        if (Math.abs(item.velocity.y) > 1.4) {
          item.velocity.y *= -0.24
          item.velocity.x *= 0.55
          item.velocity.z *= 0.55
          item.spin.multiplyScalar(0.5)
          if (Math.random() < 0.4) addGroundSplat(obj.position.x, obj.position.z, randomRange(0.15, 0.4))
        } else {
          item.settled = true
          item.velocity.set(0, 0, 0)
          item.spin.multiplyScalar(0.2)
        }
      }
    }
  }

  return {
    root,
    spawnBlood,
    splatter,
    wallSplashFrom,
    addGroundSplat,
    addWallSplat,
    addCorpsePool,
    addDebris,
    spawnGuts,
    spawnBone,
    clear,
    update,
    get counts() {
      return { ground: groundCount, wall: wallCount, debris: debris.length }
    },
    splatTexture,
    splashTexture
  }
}

export function createAudio() {
  let ctx = null
  let master = null
  let muted = false
  let ambient = null
  let noiseBuffer = null

  function ensure() {
    if (ctx) {
      if (ctx.state === 'suspended') ctx.resume()
      return ctx
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext
    if (!AudioCtx) return null
    ctx = new AudioCtx()
    master = ctx.createGain()
    master.gain.value = 0.85
    master.connect(ctx.destination)
    noiseBuffer = makeNoise(2)
    startAmbient()
    return ctx
  }

  function makeNoise(seconds) {
    const length = Math.floor(ctx.sampleRate * seconds)
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1
      last = last * 0.72 + white * 0.28
      data[i] = last
    }
    return buffer
  }

  function startAmbient() {
    if (!ctx) return
    const src = ctx.createBufferSource()
    src.buffer = noiseBuffer
    src.loop = true
    const filter = ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = 520
    filter.Q.value = 0.6
    const gain = ctx.createGain()
    gain.gain.value = 0.028
    const lfo = ctx.createOscillator()
    const lfoGain = ctx.createGain()
    lfo.frequency.value = 0.11
    lfoGain.gain.value = 0.012
    lfo.connect(lfoGain)
    lfoGain.connect(gain.gain)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(master)
    src.start()
    lfo.start()
    ambient = { src, gain, filter, lfo }
  }

  function noiseBurst({ duration = 0.3, gain = 0.2, type = 'lowpass', from = 900, to = 200, q = 1, delay = 0 }) {
    if (!ctx || muted) return
    const t = ctx.currentTime + delay
    const src = ctx.createBufferSource()
    src.buffer = noiseBuffer
    const filter = ctx.createBiquadFilter()
    filter.type = type
    filter.Q.value = q
    filter.frequency.setValueAtTime(from, t)
    filter.frequency.exponentialRampToValueAtTime(Math.max(30, to), t + duration)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.02, duration * 0.2))
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    src.connect(filter)
    filter.connect(g)
    g.connect(master)
    src.start(t)
    src.stop(t + duration + 0.05)
  }

  function tone({ freq = 220, end = 80, type = 'sine', duration = 0.25, gain = 0.15, delay = 0, vibrato = 0 }) {
    if (!ctx || muted) return
    const t = ctx.currentTime + delay
    const osc = ctx.createOscillator()
    const g = ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, end), t + duration)
    if (vibrato) {
      const lfo = ctx.createOscillator()
      const lfoGain = ctx.createGain()
      lfo.frequency.value = 22
      lfoGain.gain.value = vibrato
      lfo.connect(lfoGain)
      lfoGain.connect(osc.frequency)
      lfo.start(t)
      lfo.stop(t + duration)
    }
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.015)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    osc.connect(g)
    g.connect(master)
    osc.start(t)
    osc.stop(t + duration + 0.05)
  }

  return {
    ensure,
    get ready() { return Boolean(ctx) },
    get muted() { return muted },
    setMuted(value) {
      muted = value
      if (master) master.gain.value = muted ? 0 : 0.85
    },
    toggleMute() {
      this.setMuted(!muted)
      return muted
    },
    whoosh(heavy = false) {
      if (!ctx) return
      noiseBurst({ duration: heavy ? 0.38 : 0.22, gain: heavy ? 0.16 : 0.11, type: 'bandpass', from: heavy ? 420 : 700, to: heavy ? 160 : 260, q: 1.3 })
    },
    hit({ style = 'sharp', bone = false, heavy = false } = {}) {
      if (!ctx) return
      noiseBurst({ duration: heavy ? 0.22 : 0.14, gain: heavy ? 0.38 : 0.26, type: 'lowpass', from: 700, to: 90, q: 0.8 })
      tone({ freq: heavy ? 120 : 160, end: 42, type: 'sine', duration: heavy ? 0.3 : 0.18, gain: heavy ? 0.32 : 0.18 })
      if (bone) {
        noiseBurst({ duration: 0.09, gain: 0.32, type: 'highpass', from: 2600, to: 900, q: 0.5 })
        tone({ freq: 420, end: 90, type: 'square', duration: 0.08, gain: 0.08 })
      }
      if (style === 'blunt') {
        tone({ freq: 90, end: 38, type: 'triangle', duration: 0.25, gain: 0.22 })
      }
    },
    crack() {
      if (!ctx) return
      noiseBurst({ duration: 0.1, gain: 0.34, type: 'highpass', from: 3200, to: 800, q: 0.6 })
      tone({ freq: 700, end: 90, type: 'square', duration: 0.1, gain: 0.09 })
      tone({ freq: 260, end: 60, type: 'sawtooth', duration: 0.13, gain: 0.08 })
    },
    sever() {
      if (!ctx) return
      noiseBurst({ duration: 0.3, gain: 0.3, type: 'lowpass', from: 1800, to: 150, q: 1.2 })
      noiseBurst({ duration: 0.18, gain: 0.16, type: 'bandpass', from: 600, to: 200, q: 2 })
      tone({ freq: 180, end: 55, type: 'sawtooth', duration: 0.2, gain: 0.1, vibrato: 20 })
    },
    death() {
      if (!ctx) return
      tone({ freq: 130, end: 48, type: 'sawtooth', duration: 0.55, gain: 0.14, vibrato: 14 })
      noiseBurst({ duration: 0.5, gain: 0.14, type: 'bandpass', from: 500, to: 120, q: 1.5, delay: 0.1 })
    },
    hurt() {
      if (!ctx) return
      noiseBurst({ duration: 0.25, gain: 0.3, type: 'lowpass', from: 500, to: 80, q: 0.9 })
      tone({ freq: 95, end: 40, type: 'sine', duration: 0.28, gain: 0.25 })
    },
    metal() {
      if (!ctx) return
      tone({ freq: 1250, end: 900, type: 'triangle', duration: 0.25, gain: 0.08 })
      tone({ freq: 1870, end: 1320, type: 'sine', duration: 0.32, gain: 0.05 })
    },
    cheer(strength = 1) {
      if (!ctx || muted) return
      const duration = 1.6 + strength * 0.9
      for (let i = 0; i < 4; i++) {
        const delay = i * 0.09
        noiseBurst({ duration, gain: 0.16 * strength, type: 'bandpass', from: 400 + i * 120, to: 900 + i * 130, q: 0.8, delay })
        noiseBurst({ duration: 0.16, gain: 0.11 * strength, type: 'bandpass', from: 2200, to: 1800, q: 2, delay: delay + Math.random() * 0.5 })
      }
      tone({ freq: 190, end: 260, type: 'sawtooth', duration: 0.5, gain: 0.03 * strength, delay: 0.1 })
    },
    horn() {
      if (!ctx) return
      for (const freq of [110, 164.8, 220]) {
        tone({ freq, end: freq * 0.98, type: 'sawtooth', duration: 1.3, gain: 0.045 })
      }
      tone({ freq: 55, end: 52, type: 'triangle', duration: 1.5, gain: 0.08 })
    },
    step() {
      if (!ctx) return
      noiseBurst({ duration: 0.07, gain: 0.05, type: 'lowpass', from: 320, to: 90, q: 0.7 })
    },
    ui() {
      if (!ctx) return
      tone({ freq: 660, end: 880, type: 'triangle', duration: 0.08, gain: 0.05 })
    }
  }
}

import * as THREE from 'three'
import { applyHit } from './model.js'

const UP = new THREE.Vector3(0, 1, 0)
const tmpDir = new THREE.Vector3()
const tmpPos = new THREE.Vector3()
const tmpVec = new THREE.Vector3()

function smooth(current, target, rate, dt) {
  return current + (target - current) * Math.min(1, rate * dt)
}

export function createNPC({
  body,
  fighter,
  gore,
  audio,
  contactTexture,
  speed = 1.3,
  damage = 8,
  attackCooldown = 1.5,
  scale = 1,
  onDeath = () => {}
}) {
  body.root.scale.setScalar(scale)
  body.root.userData.npc = true
  if (body.contact) {
    body.contact.material.map = contactTexture
    body.contact.material.needsUpdate = true
  }

  const rightArm = body.parts.rightArm
  const leftArm = body.parts.leftArm
  const rightLeg = body.parts.rightLeg
  const leftLeg = body.parts.leftLeg
  const torso = body.parts.chest

  const npc = {
    body,
    fighter,
    root: body.root,
    speed,
    damage,
    cooldownMax: attackCooldown,
    cooldown: 0.4 + Math.random() * 0.8,
    attackRange: 1.95,
    state: 'approach',
    stateTime: 0,
    swingHit: false,
    deadTimer: 0,
    bleedTimer: 0,
    walkPhase: Math.random() * 10,
    yaw: Math.random() * Math.PI * 2,
    velocity: new THREE.Vector3(),
    removed: false,
    bisected: false,
    id: fighter.id,

    hit(hit) {
      if (fighter.dead) return null
      const partGroup = body.parts[hit.part] || body.parts.chest
      partGroup.getWorldPosition(tmpPos)
      const hp = fighter.health
      const result = applyHit(fighter, hit)
      if (!result.events.length) return result

      const dir = new THREE.Vector3(hit.direction?.[0] || 0, hit.direction?.[1] || 0, hit.direction?.[2] || 1).normalize()
      if (hit.style === 'blunt') audio.hit({ style: 'blunt', bone: false, heavy: hit.heavy })
      else audio.hit({ style: 'sharp', heavy: hit.heavy })

      for (const event of result.events) {
        switch (event.type) {
          case 'blood': {
            const wound = event.part === 'head' || event.part === 'jaw'
              ? tmpPos
              : this.root.position.clone().setY(event.part.includes('Leg') ? 0.75 : 1.25)
            const sprayDir = dir.clone().add(new THREE.Vector3(0, 0.15, 0)).normalize()
            gore.spawnBlood(wound, sprayDir, event.amount, { arterial: event.arterial, speed: event.arterial ? 1.35 : 1 })
            if (event.arterial) {
              gore.wallSplashFrom(wound, sprayDir, 1.3)
              gore.addCorpsePool(this.root.position, 0.8)
            }
            break
          }
          case 'sever': {
            const part = event.part
            const group = body.parts[part]
            this.root.updateMatrixWorld(true)
            const world = new THREE.Vector3()
            group.getWorldPosition(world)
            if (part === 'rightArm' && body.weaponMesh) {
              // The weapon leaves with the arm.
            }
            const side = part.includes('left') ? -1 : 1
            const vel = new THREE.Vector3(dir.x * 2.4 + side * 0.8, 2.2 + Math.random() * 1.2, dir.z * 2.4 + (Math.random() - 0.5) * 1.4)
            gore.addDebris(group, {
              velocity: vel,
              spin: new THREE.Vector3((Math.random() - 0.5) * 9, (Math.random() - 0.5) * 9, (Math.random() - 0.5) * 9)
            })
            this.addBoneToLimb(group, part)
            body.showStump(part)
            audio.sever()
            gore.spawnBlood(world, dir, 34, { arterial: true, speed: 1.4 })
            gore.addGroundSplat(world.x, world.z, 1.15)
            break
          }
          case 'break': {
            body.showBone(event.part)
            audio.crack()
            break
          }
          case 'jawOff': {
            const jaw = body.parts.jaw
            this.root.updateMatrixWorld(true)
            const world = new THREE.Vector3()
            jaw.getWorldPosition(world)
            body.showJawSocket()
            gore.addDebris(jaw, {
              velocity: new THREE.Vector3(dir.x * 2.2, 1.6, dir.z * 2.2),
              spin: new THREE.Vector3(3, 4, 2)
            })
            gore.spawnBlood(world, dir, 18)
            gore.splatter(world, dir, 0.7)
            break
          }
          case 'skullOpen': {
            const cap = body.parts.cap
            const skull = body.parts.skull
            skull.getWorldPosition(tmpPos)
            body.showBrain()
            gore.addDebris(cap, {
              velocity: new THREE.Vector3(dir.x * 2.8, 3.2, dir.z * 2.8),
              spin: new THREE.Vector3(5, 2, 7)
            })
            gore.spawnBlood(tmpPos, dir, 45, { arterial: true, speed: 1.5 })
            gore.spawnBone(tmpPos.clone().add(new THREE.Vector3(0, 0.08, 0)), new THREE.Vector3(dir.x, 2.5, dir.z))
            gore.splatter(tmpPos, dir, 1.6)
            gore.addCorpsePool(this.root.position, 1)
            audio.crack()
            break
          }
          case 'headSplit': {
            const skull = body.parts.skull
            this.root.updateMatrixWorld(true)
            skull.getWorldPosition(tmpPos)
            body.showHeadCut()
            gore.addDebris(skull, {
              velocity: new THREE.Vector3(dir.x * 2.8, 2.6, dir.z * 2.8),
              spin: new THREE.Vector3(2, 5, 6)
            })
            gore.spawnBlood(tmpPos, dir, 52, { arterial: true, speed: 1.6 })
            gore.spawnGuts(tmpPos, dir)
            gore.wallSplashFrom(tmpPos, dir, 2)
            gore.addCorpsePool(this.root.position, 1.2)
            audio.sever()
            break
          }
          case 'bisect': {
            this.root.updateMatrixWorld(true)
            const chest = body.parts.chest
            const pelvis = body.parts.pelvis
            const world = new THREE.Vector3()
            chest.getWorldPosition(world)
            body.showBisectCut('chest')
            body.showBisectCut('pelvis')
            const upper = new THREE.Vector3(dir.x * 1.8, 2.2, dir.z * 1.8)
            gore.addDebris(chest, {
              velocity: upper,
              spin: new THREE.Vector3((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 2, (Math.random() - 0.5) * 3)
            })
            const lower = pelvis
            const lowerVel = new THREE.Vector3(dir.x * 1.2 + (Math.random() - 0.5), 0.8, dir.z * 1.2 + (Math.random() - 0.5))
            gore.addDebris(lower, {
              velocity: lowerVel,
              spin: new THREE.Vector3((Math.random() - 0.5) * 4, (Math.random() - 0.5) * 2, (Math.random() - 0.5) * 4)
            })
            gore.spawnGuts(world, dir)
            gore.spawnBlood(world, dir, 70, { arterial: true, speed: 1.7 })
            gore.wallSplashFrom(world, dir, 2.4)
            gore.addCorpsePool(this.root.position, 1.9)
            this.bisected = true
            audio.sever()
            break
          }
          case 'dropWeapon': {
            // Only drop separately if the arm is still attached to the body.
            if (body.weaponMesh && body.weaponMesh.parent) {
              const weapon = body.weaponMesh
              const world = new THREE.Vector3()
              weapon.getWorldPosition(world)
              body.weaponMesh = null
              gore.addDebris(weapon, {
                velocity: new THREE.Vector3(dir.x * 2.2, 2.4, dir.z * 2.2),
                spin: new THREE.Vector3(2.5, 5, 3.5)
              })
              gore.spawnBlood(world, dir, 8)
            }
            break
          }
          case 'crack':
            audio.crack()
            break
          case 'crawl':
            break
          case 'death': {
            this.deadTimer = 0
            this.state = 'dead'
            audio.death()
            audio.cheer(1)
            gore.addCorpsePool(this.root.position, 1.5)
            onDeath(this)
            break
          }
          default:
            break
        }
      }
      if (fighter.health < hp && fighter.health > 0) {
        this.state = 'stagger'
        this.stateTime = 0
      }
      return result
    },

    addBoneToLimb(group, part) {
      const bone = new THREE.Mesh(
        new THREE.CylinderGeometry(0.025, 0.04, 0.24, 6),
        body.boneMaterial
      )
      bone.position.set(0, part.includes('Arm') ? 0.03 : 0.03, 0.02)
      bone.rotation.set(0.4, 0, 0.25)
      bone.castShadow = true
      group.add(bone)
    },

    update(dt, player, others) {
      const fighter = this.fighter
      if (fighter.dead) {
        this.deadTimer += dt
        if (!this.bisected) {
          const t = Math.min(1, Math.max(0, (this.deadTimer - 0.35) / 0.85))
          const ease = 1 - Math.pow(1 - t, 3)
          const target = this.state === 'dead' ? 1.42 : 1.2
          body.pose.rotation.x = smooth(body.pose.rotation.x, target, 4 * ease + 0.5, dt)
          body.pose.position.y = smooth(body.pose.position.y, -0.55, 2, dt)
          if (t >= 1 && body.contact) body.contact.material.opacity = 0.22
        }
        return
      }

      this.stateTime += dt
      this.cooldown = Math.max(0, this.cooldown - dt)
      const toPlayer = tmpDir.copy(player.position).sub(this.root.position)
      toPlayer.y = 0
      const distance = toPlayer.length()
      if (distance > 0.001) toPlayer.divideScalar(distance)
      const targetYaw = Math.atan2(toPlayer.x, toPlayer.z)
      let deltaYaw = targetYaw - this.yaw
      while (deltaYaw > Math.PI) deltaYaw -= Math.PI * 2
      while (deltaYaw < -Math.PI) deltaYaw += Math.PI * 2
      this.yaw += deltaYaw * Math.min(1, dt * 6)
      this.root.rotation.y = this.yaw

      if (fighter.crawling) {
        body.pose.rotation.x = smooth(body.pose.rotation.x, 1.12, 4, dt)
        body.pose.position.y = smooth(body.pose.position.y, -0.2, 4, dt)
      } else {
        body.pose.rotation.x = smooth(body.pose.rotation.x, 0, 6, dt)
        body.pose.position.y = smooth(body.pose.position.y, 0, 6, dt)
      }

      if (this.state === 'stagger') {
        const t = this.stateTime
        rightArm.rotation.x = smooth(rightArm.rotation.x, -0.25, 8, dt)
        leftArm.rotation.x = smooth(leftArm.rotation.x, 0.25, 8, dt)
        if (t > (fighter.crawling ? 0.4 : 0.32)) this.state = 'approach'
        return
      }

      // Melee attack state machine.
      if (this.state === 'windup') {
        const windup = fighter.crawling ? 0.7 : 0.5
        rightArm.rotation.x = smooth(rightArm.rotation.x, -2.25, 12, dt)
        body.parts.rightForearm.rotation.x = smooth(body.parts.rightForearm.rotation.x, -0.45, 12, dt)
        if (this.stateTime > windup) {
          this.state = 'swing'
          this.stateTime = 0
          this.swingHit = false
          audio.whoosh()
        }
        return
      }
      if (this.state === 'swing') {
        rightArm.rotation.x = smooth(rightArm.rotation.x, 0.65, 24, dt)
        body.parts.rightForearm.rotation.x = smooth(body.parts.rightForearm.rotation.x, 0.2, 20, dt)
        if (!this.swingHit && this.stateTime > 0.09) {
          this.swingHit = true
          const facing = tmpVec.set(Math.sin(this.yaw), 0, Math.cos(this.yaw))
          const toTarget = new THREE.Vector3().copy(player.position).sub(this.root.position)
          toTarget.y = 0
          const dist = toTarget.length()
          toTarget.normalize()
          if (dist < 2.35 && facing.dot(toTarget) > 0.35) {
            player.hurt(this.damage)
          }
        }
        if (this.stateTime > 0.22) {
          this.state = 'recover'
          this.stateTime = 0
        }
        return
      }
      if (this.state === 'recover') {
        rightArm.rotation.x = smooth(rightArm.rotation.x, -0.2, 8, dt)
        body.parts.rightForearm.rotation.x = smooth(body.parts.rightForearm.rotation.x, 0, 8, dt)
        if (this.stateTime > 0.3) {
          this.state = 'approach'
          this.cooldown = this.cooldownMax * (0.85 + Math.random() * 0.35)
        }
        return
      }

      // Approach / circle.
      if (!fighter.hasWeapon) {
        // Disarmed gladiators can only shove weakly.
        if (distance < 1.4 && this.cooldown <= 0) {
          player.hurt(Math.max(2, Math.round(this.damage * 0.3)))
          this.cooldown = 1.8
        }
      } else if (distance < this.attackRange && this.cooldown <= 0) {
        this.state = 'windup'
        this.stateTime = 0
        return
      }

      const crawlFactor = fighter.crawling ? 0.32 : 1
      if (distance > (fighter.crawling ? 1.2 : 1.7)) {
        const move = this.speed * crawlFactor * (fighter.hasWeapon ? 1 : 0.8)
        this.root.position.x += toPlayer.x * move * dt
        this.root.position.z += toPlayer.z * move * dt
        this.walkPhase += dt * (fighter.crawling ? 3 : 7)
        if (!fighter.crawling) {
          const swing = Math.sin(this.walkPhase) * 0.5
          leftLeg.rotation.x = swing
          rightLeg.rotation.x = -swing
          if (this.state !== 'windup' && this.state !== 'swing') {
            leftArm.rotation.x = -swing * 0.7
            rightArm.rotation.x = swing * 0.55 - 0.2
          }
        }
      } else {
        leftLeg.rotation.x = smooth(leftLeg.rotation.x, 0, 8, dt)
        rightLeg.rotation.x = smooth(rightLeg.rotation.x, 0, 8, dt)
        leftArm.rotation.x = smooth(leftArm.rotation.x, 0.1, 8, dt)
        rightArm.rotation.x = smooth(rightArm.rotation.x, -0.2, 8, dt)
      }

      // Separation from other fighters.
      if (others) {
        for (const other of others) {
          if (other === this || other.removed || other.fighter.dead) continue
          const dx = this.root.position.x - other.root.position.x
          const dz = this.root.position.z - other.root.position.z
          const d2 = dx * dx + dz * dz
          if (d2 < 0.95 && d2 > 0.0001) {
            const d = Math.sqrt(d2)
            const push = (0.95 - d) * 0.5
            this.root.position.x += (dx / d) * push
            this.root.position.z += (dz / d) * push
          }
        }
      }

      // Arena bounds.
      const radius = Math.hypot(this.root.position.x, this.root.position.z)
      if (radius > 16.35) {
        this.root.position.x = (this.root.position.x / radius) * 16.35
        this.root.position.z = (this.root.position.z / radius) * 16.35
      }

      // Wounded gladiators drip blood.
      this.bleedTimer -= dt
      if (this.bleedTimer <= 0 && fighter.health < fighter.maxHealth) {
        this.bleedTimer = fighter.crawling ? 0.9 : 0.55
        const wound = this.root.position.clone().setY(fighter.crawling ? 0.45 : 1.1)
        gore.spawnBlood(wound, new THREE.Vector3(Math.sin(this.yaw + 1.5), 0.2, Math.cos(this.yaw + 1.5)), 2, { speed: 0.4 })
        if (Math.random() < 0.25) gore.addGroundSplat(this.root.position.x, this.root.position.z, 0.22)
      }
    },

    dispose() {
      this.removed = true
      if (this.root.parent) this.root.parent.remove(this.root)
    }
  }

  return npc
}

