:root {
  --gold: #d8b45f;
  --gold-bright: #f3d992;
  --gold-dim: #8d6a2c;
  --blood: #8a1010;
  --blood-bright: #c31d1d;
  --ink: #0d0907;
  --parchment: #e9ddc4;
  --serif: "Copperplate", "Cinzel", "Trajan Pro", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  --body: "Gill Sans", "Segoe UI", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #0a0705;
  color: var(--parchment);
  font-family: var(--body);
  overflow: hidden;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #0a0705;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.hidden { display: none !important; }

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at center, transparent 46%, rgba(8, 4, 2, 0.55) 100%),
    linear-gradient(180deg, rgba(0,0,0,0.2), transparent 14%, transparent 78%, rgba(0,0,0,0.4));
  mix-blend-mode: multiply;
  z-index: 2;
}

#grain {
  position: absolute;
  inset: -20%;
  pointer-events: none;
  opacity: 0.055;
  z-index: 3;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.75'/%3E%3C/svg%3E");
  animation: grainShift 0.7s steps(3) infinite;
}

@keyframes grainShift {
  0% { transform: translate(0, 0); }
  33% { transform: translate(-1.5%, 1%); }
  66% { transform: translate(1%, -1.4%); }
  100% { transform: translate(0, 0); }
}

#blood-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 18;
  opacity: 0;
  background:
    radial-gradient(ellipse at 50% 52%, transparent 25%, rgba(126, 5, 5, 0.4) 72%, rgba(78, 2, 2, 0.85) 100%);
  transition: opacity 0.2s ease;
}

#blood-flash.on { opacity: 1; }

#damage-ring {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 17;
  opacity: 0;
  box-shadow: inset 0 0 130px 36px rgba(120, 0, 0, 0.72);
  transition: opacity 0.25s ease;
}

#damage-ring.on { opacity: 1; }

/* ============ HUD ============ */
#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: max(18px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.eyebrow {
  font-family: var(--serif);
  font-size: 10px;
  letter-spacing: 0.26em;
  color: var(--gold);
  text-transform: uppercase;
  opacity: 0.92;
}

.vitality { width: min(320px, 30vw); }
.vitality-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 6px;
}
#health-number {
  font-family: var(--serif);
  font-size: 19px;
  line-height: 1;
  color: var(--gold-bright);
  text-shadow: 0 2px 4px #000;
}
.health-track {
  position: relative;
  height: 15px;
  background: rgba(10, 5, 3, 0.78);
  border: 1px solid rgba(216, 180, 95, 0.5);
  box-shadow: inset 0 0 10px rgba(0,0,0,0.8), 0 0 12px rgba(0,0,0,0.5);
  clip-path: polygon(0 0, 100% 0, 98% 100%, 1.5% 100%);
}
.health-track::after {
  content: "";
  position: absolute;
  inset: 3px;
  background-image: repeating-linear-gradient(90deg, transparent 0 9%, rgba(0,0,0,0.35) 9% 10%);
  pointer-events: none;
}
.health-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(180deg, #c5231c 0%, #8e0d0c 42%, #4d0606 100%);
  box-shadow: 0 0 18px rgba(200, 24, 20, 0.55);
  transition: width 0.32s cubic-bezier(.2,.8,.3,1);
}
.health-fill.low { animation: lowPulse 0.8s infinite alternate; }
@keyframes lowPulse { from { filter: brightness(0.8); } to { filter: brightness(1.5); } }
.vitality-under {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  letter-spacing: 0.2em;
  color: rgba(233, 221, 196, 0.62);
  margin-top: 5px;
  font-family: var(--serif);
}
.dodge-label { color: rgba(216, 180, 95, 0.65); }

.wave-panel {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 150px;
  padding-top: 2px;
}
.wave-number {
  font-family: var(--serif);
  font-size: 38px;
  line-height: 0.95;
  color: var(--gold-bright);
  text-shadow: 0 3px 0 #38170a, 0 0 26px rgba(216, 180, 95, 0.35);
  letter-spacing: 0.04em;
}
.foes-left {
  font-size: 9px;
  letter-spacing: 0.22em;
  color: rgba(233, 221, 196, 0.72);
}

.tally {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  gap: 0 10px;
  text-align: right;
  min-width: 150px;
  justify-content: end;
}
.tally .eyebrow { grid-column: 1; }
.kill-count {
  grid-column: 2;
