}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 42px;
  height: 42px;
  margin: -21px 0 0 -21px;
  opacity: 0.92;
  transition: transform 0.08s ease, opacity 0.2s;
}
.ch-dot {
  position: absolute;
