}
.ch-bar {
  position: absolute;
  background: rgba(243, 217, 146, 0.85);
  box-shadow: 0 0 4px rgba(0,0,0,0.8);
}
.ch-top, .ch-bottom { width: 1.5px; height: 7px; left: 50%; margin-left: -0.75px; }
.ch-left, .ch-right { height: 1.5px; width: 7px; top: 50%; margin-top: -0.75px; }
.ch-top { top: 2px; }
.ch-bottom { bottom: 2px; }
.ch-left { left: 2px; }
.ch-right { right: 2px; }
.crosshair.strike { transform: scale(1.45); }
.crosshair.strike .ch-bar { background: #ff6a4a; }

.wave-banner {
  position: absolute;
  left: 50%;
  top: 27%;
  transform: translateX(-50%);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 20px 64px;
  background: linear-gradient(90deg, transparent, rgba(9, 5, 3, 0.82) 18%, rgba(9, 5, 3, 0.82) 82%, transparent);
  animation: bannerIn 0.55s cubic-bezier(.2,.9,.2,1);
}
.wave-banner::before, .wave-banner::after {
  content: "";
  width: min(440px, 60vw);
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold-dim), transparent);
}
.wave-banner.out { animation: bannerOut 0.5s forwards; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, 16px) scale(0.96); } to { opacity: 1; transform: translate(-50%, 0) scale(1); } }
@keyframes bannerOut { to { opacity: 0; transform: translate(-50%, -10px) scale(1.02); } }
.banner-kicker {
  font-family: var(--serif);
  font-size: 10px;
  letter-spacing: 0.42em;
  color: var(--gold);
  text-transform: uppercase;
}
.banner-title {
  font-family: var(--serif);
  font-size: clamp(42px, 7vw, 84px);
