  letter-spacing: 0.3em;
  font-size: 12px;
  color: #ffd98a;
  padding: 8px 22px;
  background: linear-gradient(90deg, transparent, rgba(72, 8, 8, 0.72), transparent);
  text-shadow: 0 0 18px rgba(255, 180, 70, 0.7);
  animation: toastIn 0.3s ease;
}
.toast.pop { animation: toastPop 0.35s ease; }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes toastPop { 0% { transform: translateX(-50%) scale(1); } 40% { transform: translateX(-50%) scale(1.12); } 100% { transform: translateX(-50%) scale(1); } }

.hud-bottom {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 0 max(22px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}
.weapon-panel {
  display: flex;
  align-items: center;
  gap: 12px;
