  font-family: var(--serif);
  font-size: 9px;
  letter-spacing: 0.2em;
  color: rgba(216, 180, 95, 0.55);
  border: 1px solid rgba(216, 180, 95, 0.22);
  padding: 4px 7px;
}
.control-hint {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px 14px;
  font-size: 8.5px;
  letter-spacing: 0.18em;
  color: rgba(233, 221, 196, 0.5);
  padding-bottom: 5px;
}
.control-hint b { color: rgba(216, 180, 95, 0.8); font-weight: 600; }
.sound-hint { padding-bottom: 2px; }
.mute-btn, .ghost-btn {
  pointer-events: auto;
  background: transparent;
  color: rgba(233, 221, 196, 0.55);
  border: 1px solid rgba(216, 180, 95, 0.28);
  font-family: var(--serif);
  font-size: 9px;
