}
.mute-btn:hover, .ghost-btn:hover { color: var(--gold-bright); border-color: var(--gold); background: rgba(216,180,95,0.08); }

.combo {
  position: absolute;
  right: 7vw;
  top: 38%;
  font-family: var(--serif);
  font-size: 26px;
  letter-spacing: 0.1em;
  color: var(--gold-bright);
  text-shadow: 0 2px 0 #3a1206, 0 0 24px rgba(216,180,95,0.4);
  animation: comboIn 0.4s ease;
}
@keyframes comboIn { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: none; } }

/* ============ Screens ============ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.title-screen {
  background:
    radial-gradient(ellipse at 50% 44%, rgba(10, 6, 4, 0.22) 0%, rgba(10, 6, 4, 0.48) 48%, rgba(8, 4, 2, 0.9) 100%),
    linear-gradient(90deg, rgba(8,4,2,0.8) 0%, transparent 24%, transparent 76%, rgba(8,4,2,0.8) 100%);
  pointer-events: auto;
}
