.ghost-btn { margin-top: 10px; display: block; margin-left: auto; margin-right: auto; }

/* ============ Loading ============ */
.loading {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
